window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 736, "text": "Что нужно знать водителю в этой ситуации?", "topic": "Дорожні знаки та розмітка", "options": ["Встречный транспорт может подрезать угол.", "Впереди дорожная разметка.", "Впереди дорога переходит в двойную проезжую часть.", "Следующий за ним транспорт может срезать угол."], "correct": 0, "expl": "На зображенні водій наближається до вигину дороги; на такій ділянці головна прихована небезпека — це транспорт, що рухається назустріч і може зрізати шлях по внутрішній частині повороту, заїжджаючи на вашу смугу.", "explSpecific": "Правильно — «Встречный транспорт может подрезать угол». «Дорожня розмітка» і «дорога переходить у подвійну проїжджу частину» не є головним уроком цієї ситуації; «транспорт позаду може зрізати кут» переплутує джерело небезпеки — саме зустрічний, а не задній транспорт становить загрозу на вигині.", "img": "q736.png"}, {"num": 737, "text": "Какое действие оказывает алкоголь на поведение водителя?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Под действием алкоголя водитель становится более сосредоточенным.", "Снижает концентрацию.", "Придают водителю уверенность.", "Алкоголь ускоряет реакцию водителя."], "correct": 1, "expl": "Алкоголь знижує концентрацію уваги водія, погіршуючи здатність зосереджуватися на дорозі.", "explSpecific": "Правильно — «Снижает концентрацию». Твердження про підвищену зосередженість, впевненість чи прискорену реакцію оманливі — насправді алкоголь погіршує реальні здібності водія."}, {"num": 738, "text": "Из чего состоит дорога типа 2+1?", "topic": "Обгін та зміна смуги руху", "options": ["Две полосы движения в одном направлении и одной полосы движения в противоположном направлении.", "Две автомагистральные полосы в одном направлении и одна не автомагистральная полоса в противоположном направлении.", "Две не автомагистральные полосы и одна автомагистральная полоса в двух направлениях.", "Две автомагистральные полосы и одна не автомагистральная полоса в двух направлениях."], "correct": 0, "expl": "Дорога типу «2+1» — особлива схема, де почергово то один, то інший напрямок отримує дві смуги для безпечного обгону, а протилежний — одну.", "explSpecific": "Правильно — перший варіант, що просто й точно описує схему «дві смуги в одному напрямку, одна в протилежному». Інші варіанти вигадують статус «автомагістральних» смуг, який не відповідає визначенню дороги 2+1."}, {"num": 739, "text": "Что делать водителю если он хочет воспользоваться мобильным телефоном?", "topic": "Паркування та зупинка", "options": ["Снижайте скорость, проявляйте осторожность и будьте внимательны к другим участкам дорожного движения.", "Въезжайте и остановитесь в безопасном месте.", "Не разговаривайте долго.", "Дождаться большего промежутка между вашим и впереди и впереди идущим автомобилем и продолжайте движение с нормальной скоростью."], "correct": 0, "expl": "Правила відрізняють ручне використання телефону за кермом (заборонене) від використання через гучний зв'язок (дозволене за умови особливої обережності) — саме про останній випадок тут ідеться.", "explSpecific": "Правильно — «Снижайте скорость, проявляйте осторожность и будьте внимательны к другим участкам дорожного движения» (використання через гучний зв'язок з підвищеною обачністю). «Заїхати і зупинитися» — правило саме для ручного телефону; «не розмовляти довго» і «почекати проміжок і їхати як звичайно» не відповідають вимозі підвищеної обачності під час розмови за кермом."}, {"num": 740, "text": "В чем водителю следует убедиться перед выходом из автомобиля на оживленной дороге?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Чтобы пассажиры сначала открыли дверь.", "Прежде чем открыть дверь, водитель должен убедиться, что это безопасно.", "Что рычаг переключения передач находится в нейтральном положении.", "Что колеса расположены прямо."], "correct": 1, "expl": "Перш ніж вийти з автомобіля на жвавій дорозі, водій повинен переконатися, що відчинити двері безпечно — немає транспорту чи велосипедистів, які наближаються.", "explSpecific": "Правильно — «Прежде чем открыть дверь, водитель должен убедиться, что это безопасно». Покладання на пасажирів чи перевірка нейтральної передачі й положення коліс не мають стосунку до головної небезпеки — транспорту, що наближається ззовні."}, {"num": 741, "text": "Что в данной ситуации следует учитывать водителю, движущемуся по правой полосе дороги с двусторонним движением?", "topic": "Обгін та зміна смуги руху", "options": ["Повышенная видимость.", "Боковой ветер может столкнуть мотоциклиста с пути.", "Встречное давление.", "Мотоциклиста может развернуться."], "correct": 1, "expl": "Рухаючись правою смугою дороги з двостороннім рухом за поганої погоди, водій повинен пам'ятати, що бічний вітер може збити мотоцикліста з його траєкторії, підштовхнувши його у вашу смугу.", "explSpecific": "Правильно — «Боковой ветер может столкнуть мотоциклиста с пути». «Підвищена видимість» не відповідає дощовим умовам на зображенні; можливість розвороту мотоцикліста — малоймовірний сценарій.", "img": "q741.png"}, {"num": 742, "text": "Что делать водителю, если его автомобиль сломался в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Пройти до конца туннеля, чтобы позвонить в Гарда.", "Поймать попутную машину, чтобы добраться до ближайшей зоны обслуживания и обратится за помощью.", "Воспользоваться телефоном экстренной связи, чтобы вызвать помощь.", "Остановить проезжающего автомобилиста и попросить о помощи."], "correct": 2, "expl": "Якщо автомобіль зламався в тунелі, водій повинен скористатися екстреним телефоном зв'язку, розташованим у тунелі, для виклику допомоги.", "explSpecific": "Правильно — «Воспользоваться телефоном экстренной связи, чтобы вызвать помощь». Прохід до кінця тунелю чи ловіння попутної машини — небезпечні й непотрібні дії, коли поруч є спеціально обладнаний телефон."}, {"num": 743, "text": "Что должен сделать водитель перед буксировкой трейлера?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Убедиться, что в трейлере сидят только взрослые пассажиры.", "Убедиться, что все пассажиры надежно сидят в трейлере.", "Установить расширенное зеркало только со стороны водителя.", "Установить расширенные зеркала на буксирующем автомобиле."], "correct": 3, "expl": "Буксируючи причіп, який ширший за сам автомобіль чи закриває задній огляд, водій повинен встановити розширені бокові дзеркала на буксирувальному авто для належного огляду.", "explSpecific": "Правильно — «Установить расширенные зеркала на буксирующем автомобиле». Вимоги щодо пасажирів у причепі — geть інша тема; дзеркало лише з боку водія недостатньо для повного огляду з обох боків причепа."}, {"num": 744, "text": "Что следует делать водителю при буксировке прицепа с высоким и широким кузовом?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Двигаться с красным флажком сзади слева от прицепа.", "Использовать дополнительные зеркала для наблюдения за другим транспортом.", "Двигаться с красным флажком спереди справа от прицепа.", "Ехать с постоянно мигающими аварийными огнями."], "correct": 1, "expl": "Той самий принцип — буксируючи причіп із високим і широким кузовом, водій повинен використовувати додаткові дзеркала для спостереження за іншим транспортом.", "explSpecific": "Правильно — «Использовать дополнительные зеркала для наблюдения за другим транспортом». Червоний прапорець чи постійно мигаючі аварійні вогні не є стандартною вимогою; додаткові дзеркала компенсують обмежений огляд."}, {"num": 745, "text": "Что делать водителю, если окна автомобиля покрыты льдом?", "topic": "Погодні умови та видимість", "options": ["Полностью очистить все окна от льда.", "Использовать кипяток для очистки стекол от льда.", "Двигаться медленно, пока обогреватель и система обдува стекол не нагреют стекла и не очистят лед.", "Расчистить достаточно пространства на лобовом стекле, чтобы обеспечить достаточный обзор."], "correct": 0, "expl": "Перш ніж рушати, водій повинен повністю очистити від льоду ВСІ вікна автомобіля, а не лише невелику ділянку для мінімального огляду.", "explSpecific": "Правильно — «Полностью очистить все окна от льда». Використання окропу небезпечне (може тріснути скло); рух з частково розмороженими вікнами чи розчищення лише невеликої ділянки не забезпечують повного огляду."}, {"num": 746, "text": "Что делать водителю, если его автомобиль остановится в туннеле из- за поломки или аварии?", "topic": "Автомагістраль і тунелі", "options": ["Развернуть автомобиль в сторону выезда.", "Подать сигнал другому транспорту о возможности обгона.", "Дождаться в автомобиле прибытия помощи.", "Обратиться за помощью с аварийной станции."], "correct": 3, "expl": "Якщо автомобіль зупинився в тунелі через поломку чи аварію, водій повинен звернутися за допомогою з найближчої аварійної станції, обладнаної для цього.", "explSpecific": "Правильно — «Обратиться за помощью с аварийной станции». Розворот у тунелі для виїзду небезпечний і часто фізично неможливий; очікування в автомобілі без активних дій не вирішує ситуацію."}, {"num": 747, "text": "Что делать водителю, если окна и зеркала автомобиля покрыты льдом?", "topic": "Погодні умови та видимість", "options": ["Использовать кипяток с солью для очистки стекол от льда.", "Двигаться на пониженной скорости, пока система отопления автомобиля не очистит лед.", "Перед поездкой включить систему обогрева и очистить лед скребком.", "Включить дворники."], "correct": 2, "expl": "Правильний спосіб очистити вкриті льодом вікна й дзеркала перед поїздкою — увімкнути систему обігріву заздалегідь і додатково використати скребок.", "explSpecific": "Правильно — «Перед поездкой включить систему обогрева и очистить лед скребком». Окріп із сіллю може пошкодити скло; рух зі зниженою швидкістю, поки лід сам розтане, небезпечно відкладає повноцінний огляд."}, {"num": 748, "text": "Что делать водителю, если на окнах автомобиля образовался конденсат?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Убедиться, что все отверстия для обдува стекла и окна закрыты.", "Проехать несколько километров с открытым окном.", "Протереть окна тканью, а затем воспользоваться системой стекло- обогрева.", "Протереть окна тыльной стороной руки."], "correct": 2, "expl": "Щоб позбутися конденсату на склі, спершу варто протерти його тканиною, а потім увімкнути систему обігріву/обдуву скла для підтримання чистоти надалі.", "explSpecific": "Правильно — «Протереть окна тканью, а затем воспользоваться системой стекло-обогрева». Закриття всіх отворів обдуву, навпаки, посилює запотівання; їзда з відкритим вікном чи протирання рукою — тимчасові рішення."}, {"num": 749, "text": "Как солнечный свет может повлиять на видимость в автомобиле с грязными окнами?", "topic": "Погодні умови та видимість", "options": ["Он может улучшить видимость.", "Он может значительно снизить видимость.", "Это может привести к тому, что объекты будут казаться дальше, чем они есть на самом деле.", "Это может привести к тому, что объекты будут казаться ближе, чем они есть на самом деле."], "correct": 1, "expl": "Сонячне світло, що проходить крізь брудні вікна, розсіюється й засліплює водія значно сильніше, ніж крізь чисте скло, суттєво погіршуючи видимість.", "explSpecific": "Правильно — «Он может значительно снизить видимость». Твердження про покращення видимості чи спотворення відстані до об'єктів не відображають головний ефект — засліплення від розсіяного світла на брудному склі."}, {"num": 750, "text": "На что водителю следует обратить внимание перед тем, как начать движение задним ходом?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Посмотреть только во внутреннее зеркало.", "Посмотреть через правое и левое плечо и сзади.", "Посмотреть только в наружные зеркала заднего вида.", "Посмотреть через правое плечо."], "correct": 1, "expl": "Перед рухом заднім ходом водій повинен оглянути ситуацію повністю — через обидва плеча і безпосередньо ззаду, а не покладатися лише на дзеркала.", "explSpecific": "Правильно — «Посмотреть через правое и левое плечо и сзади». Використання лише внутрішнього чи лише зовнішніх дзеркал залишає значні сліпі зони, які видно тільки при прямому погляді через плече."}, {"num": 751, "text": "На что следует обратить внимание водителю перед тем, как начать движение задним ходом на автомобиле, оборудованном внешним звуковым сигнальным устройством?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Необходимо осмотреть зоны спереди, с боковой и задней части транспортного средства, включая слепые зоны.", "Необходимо осмотреть только слепые зоны.", "Никаких особых наблюдений не требуется, так как прохожие увидят автомобиль.", "Водитель должен открыть свою дверь и посмотреть назад."], "correct": 0, "expl": "Навіть маючи зовнішній звуковий сигнал заднього ходу, водій не звільняється від обов'язку особисто оглянути всі зони навколо авто, включно зі сліпими.", "explSpecific": "Правильно — «Необходимо осмотреть зоны спереди, с боковой и задней части транспортного средства, включая слепые зоны». Обмеження огляду лише сліпими зонами чи покладання виключно на звуковий сигнал — небезпечне спрощення."}, {"num": 752, "text": "Что должен делать водитель, если он намеревается выехать на второстепенную дорогу?", "topic": "Загальні правила та поведінка на дорозі", "options": ["При движении задним ходом полностью сфокусируйтесь на зеркале левой двери.", "Внимательно осмотреться вокруг перед тем, как начать движение задним ходом и во время него.", "Полностью открыть левую дверь, чтобы посмотреть назад.", "Перед тем, как начать движение задним ходом, наклонить наружные зеркала заднего вида вниз."], "correct": 1, "expl": "Виїжджаючи заднім ходом на другорядну дорогу, водій повинен уважно оглядатися і перед початком маневру, і безперервно протягом усього його виконання.", "explSpecific": "Правильно — «Внимательно осмотреться вокруг перед тем, как начать движение задним ходом и во время него». Фокус лише на одному дзеркалі чи відкриття дверей для огляду — часткові чи незручні заміни повноцінного спостереження."}, {"num": 753, "text": "Что делать водителю перед тем, как отправиться в путь в сложных погодных условиях?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Залить охлаждающую жидкость в бачок омывателя ветрового стекла.", "Уменьшить давление в шинах, чтобы обеспечить лучшее сцепление с дорогой.", "Уточнить прогноз погоды для запланированного маршрута.", "Увеличить давление в шинах, чтобы обеспечить лучшее сцепление с дорогой."], "correct": 2, "expl": "Перед поїздкою у складних погодних умовах варто заздалегідь перевірити прогноз погоди для маршруту, щоб оцінити ризики і за потреби скоригувати план поїздки.", "explSpecific": "Правильно — «Уточнить прогноз погоды для запланированного маршрута». Заливання охолоджуючої рідини в бачок омивача — технічна помилка (це різні рідини); зміна тиску в шинах в жоден бік не є правильною підготовкою до складної погоди."}, {"num": 754, "text": "Что следует делать водителю, если он намеревается двигаться задним ходом в сторону зоны, которую он не видит?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Открыть водительскую дверь и посмотреть назад.", "Обратиться за помощью к тому, кто сможет помочь безопасно совершить этот маневр.", "При движении задним ходом посмотреть в ближнее (левое) зеркало.", "Открыть водительское окно и посмотреть назад."], "correct": 1, "expl": "Якщо зона позаду не проглядається, найбезпечніший вихід — попросити когось із пасажирів чи перехожих допомогти, спостерігаючи й підказуючи під час маневру.", "explSpecific": "Правильно — «Обратиться за помощью к тому, кто сможет помочь безопасно совершить этот маневр». Відчинення дверей чи вікна для огляду назад під час руху — незручний і небезпечний спосіб."}, {"num": 755, "text": "Какое влияние может оказать сырая погода на наружные зеркала автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Капли воды могут сделать так, что отраженный объект будет казаться ближе, чем он есть на самом деле.", "Капли воды могут затенить отражение.", "Вода может вызвать короткое замыкание в зеркалах с электроподогревом.", "Капли воды помогают содержать их в чистоте."], "correct": 1, "expl": "Краплі дощу на дзеркалах спотворюють і затемнюють відображення, ускладнюючи чітке бачення транспорту позаду чи збоку.", "explSpecific": "Правильно — «Капли воды могут затенить отражение». Твердження, що краплі роблять об'єкт ближчим чи допомагають чистоті дзеркал, — вигадані ефекти."}, {"num": 756, "text": "Что следует делать водителю, чтобы не терять бдительности во время долгой поездки?", "topic": "Швидкісний режим", "options": ["Увеличить циркуляцию воздуха и при необходимости, остановиться.", "Включить обогреватель, чтобы обеспечить комфорт водителя.", "Увеличить скорость, чтобы сократить длительность поездки.", "Держать радио включенным, а окна закрытыми."], "correct": 0, "expl": "Щоб не втратити пильність у довгій поїздці, водієві варто збільшити циркуляцію свіжого повітря в салоні і за потреби зупинитися для перерви.", "explSpecific": "Правильно — «Увеличить циркуляцию воздуха и при необходимости, остановиться». Увімкнення обігрівача, збільшення швидкості для скорочення поїздки чи закриті вікна з радіо — не борються з утомою, а деякі навіть посилюють сонливість."}, {"num": 757, "text": "Что следует делать водителю, чтобы не терять бдительности во время долгой поездки?", "topic": "Паркування та зупинка", "options": ["Опустить окно и впустить свежий воздух.", "Увеличить температуру в автомобиле.", "Внимательно послушать радио.", "Остановиться, припарковаться в безопасном месте и выпить чашку кофе."], "correct": 3, "expl": "Щоб не втратити пильність у довгій поїздці, водієві варто зупинитися в безпечному місці й зробити перерву — наприклад, випити кави, а не намагатися боротися із втомою на ходу.", "explSpecific": "Правильно — «Остановиться, припарковаться в безопасном месте и выпить чашку кофе». Відкрите вікно, підвищена температура в салоні чи уважне слухання радіо — неефективні й тимчасові способи боротьби зі втомою під час самого руху."}, {"num": 758, "text": "Когда следует использовать ручной тормоз для остановки автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Только при движении вверх по склону.", "В любое время.", "Как правило, никогда.", "Только при движении вниз по склону."], "correct": 2, "expl": "Ручний (стоянковий) гальмо діє різко й лише на задні колеса без антиблокувальної системи, тому як загальне правило його НЕ використовують для зупинки автомобіля під час руху — лише для утримання вже нерухомого авто.", "explSpecific": "Правильно — «Как правило, никогда» — ручний гальмо не призначений для гальмування рухомого автомобіля через ризик заблокувати задні колеса й спричинити занос (саме про це наступне питання цієї теми). «У будь-який час» прямо суперечить цій обережності; прив'язка лише до підйому чи спуску так само не відповідає загальному правилу."}, {"num": 759, "text": "Какая опасность может возникнуть при включении ручного (стояночного) тормоза во время движения автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Нет никакой опасности - автомобиль не занесет, так как ручной тормоз можно быстро отпустить.", "Двигатель заглохнет, как только ручной тормоз будет задействован на высокой скорости.", "Колеса могут заблокироваться и привести к заносу автомобиля.", "Система ABS может отключиться и привести к заносу автомобиля."], "correct": 2, "expl": "Ручний гальмо діє лише на задні колеса напряму й різко, без антиблокувальної системи, тому його активація на швидкості може миттєво заблокувати задні колеса й спричинити занос.", "explSpecific": "Правильно — «Колеса могут заблокироваться и привести к заносу автомобиля». Твердження про відсутність небезпеки, глухнення двигуна чи відключення ABS через ручний гальмо — вигадані, технічно необґрунтовані сценарії."}, {"num": 760, "text": "На что, скорее всего, указывает легкость рулевого управления?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Гравийная поверхность.", "Обледеневшая дорога.", "Гладкая дорога.", "Влажная дорога."], "correct": 1, "expl": "Незвична легкість керма (втрата звичного опору) часто свідчить про різке зниження зчеплення передніх коліс з дорогою — типовий прояв ожеледиці.", "explSpecific": "Правильно — «Обледеневшая дорога». Гравійна, гладка чи волога поверхня зазвичай не дають настільки різкого й характерного полегшення керма, як саме ожеледиця."}, {"num": 761, "text": "Как преодолеть крутой спуск в снежную или морозную погоду при движении по склону?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Включить более высокую передачу, чем обычно, чтобы избежать пробуксовки колес.", "Держать сцепление нажатым и медленно затормозить.", "Заранее включить пониженную передачу и использовать плавное торможение, чтобы снизить скорость.", "Всегда держаться ближе к левой стороне и короткими резкими нажатиями на педаль тормоза снизить скорость."], "correct": 2, "expl": "На крутому спуску в мороз чи сніг найбезпечніший спосіб — заздалегідь перейти на понижену передачу і використовувати плавне, м'яке гальмування, щоб не спровокувати занос.", "explSpecific": "Правильно — «Заранее включить пониженную передачу и использовать плавное торможение, чтобы снизить скорость». Вища передача, навпаки, збільшує ризик пробуксовки; тримання зчеплення нажатим знімає гальмування двигуном; короткі різкі натискання гальма на слизькій дорозі провокують занос."}, {"num": 762, "text": "Что делать водителю перед тем, как отправиться в путь в сложных погодных условиях?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Заполнить бачок омывателя ветрового стекла.", "Долить охлаждающую жидкость в коробку передач.", "Увеличить давление в шинах, чтобы обеспечить лучшее сцепление с дорогой.", "Уменьшить давление в шинах, чтобы обеспечить лучшее сцепление с дорогой."], "correct": 0, "expl": "Перед поїздкою у складних погодних умовах слід перевірити рівень омивальної рідини для скла — вона критично потрібна для підтримання чистого огляду під час дощу, снігу чи бризок з дороги.", "explSpecific": "Правильно — «Заполнить бачок омывателя ветрового стекла». Доливання охолоджуючої рідини в коробку передач — технічна помилка (це різні системи); зміна тиску в шинах у будь-який бік не є правильною підготовкою до складної погоди."}, {"num": 763, "text": "Почему трактор должен двигаться медленнее на неровном дорожном покрытии?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Чтобы избежать сильного подпрыгивания.", "Чтобы избежать пролива топлива из бака.", "Чтобы снизить дорожный шум.", "Чтобы поддерживать давление в шинах."], "correct": 0, "expl": "На нерівному дорожньому покритті трактор повинен рухатися повільніше, щоб уникнути сильного підстрибування, яке може призвести до втрати контролю.", "explSpecific": "Правильно — «Чтобы избежать сильного подпрыгивания». Розлив палива, зниження шуму чи підтримання тиску в шинах не є основною причиною зниження швидкості на нерівній дорозі."}, {"num": 764, "text": "Когда следует использовать задние противотуманные фары?", "topic": "Погодні умови та видимість", "options": ["Задние противотуманные фары следует использовать только на рассвете и в сумерках.", "При движении в густом тумане или во время снега.", "Всегда следует использовать задние противотуманные фары.", "Когда разбиты оба задних фонаря."], "correct": 1, "expl": "Задні протитуманні фари підвищеної яскравості призначені для використання саме в густому тумані чи під час сильного снігопаду, коли звичайних задніх вогнів недостатньо, щоб вас помітили ззаду.", "explSpecific": "Правильно — «При движении в густом тумане или во время снега». Використання лише на світанку й у сутінках чи завжди — не відповідає вузькому призначенню саме протитуманних задніх вогнів."}, {"num": 765, "text": "Вы едете в тумане. Когда следует использовать задние противотуманные фары повышенной яркости?", "topic": "Погодні умови та видимість", "options": ["Когда видимость уменьшается до 100 метров (328 футов) или меньше.", "Когда видимость уменьшается до 125 метров (408 футов) или меньше.", "Когда видимость уменьшается до 150 метров (490 футов) или меньше.", "Когда видимость уменьшается до 175 метров (572 футов) или меньше."], "correct": 0, "expl": "Офіційний поріг для увімкнення задніх протитуманних фар підвищеної яскравості — видимість 100 метрів або менше.", "explSpecific": "Правильно — «100 метров». Інші відстані (125, 150, 175 метрів) не відповідають встановленому офіційному порогу."}, {"num": 766, "text": "Что делать водителю при выходе из строя лампы правой фары при движении ночью?", "topic": "Погодні умови та видимість", "options": ["Отправиться в путь со включенными аварийными огнями.", "Временно заменить ее лампой левой фары.", "Немедленно заменить лампу.", "Временно заменить ее на лампу стоп-сигнала."], "correct": 2, "expl": "Якщо права фара вийшла з ладу під час нічної поїздки, правильна дія — негайно замінити лампу, а не імпровізувати чи продовжувати рух з несправним освітленням.", "explSpecific": "Правильно — «Немедленно заменить лампу». Поїздка з аварійними вогнями чи тимчасова заміна лампою з іншого боку/стоп-сигналу — технічно неправильні імпровізації."}, {"num": 767, "text": "Какое влияние на водителей, едущих по встречной полосе, может оказать вождение с одной фарой ночью?", "topic": "Обгін та зміна смуги руху", "options": ["Это может позволить им более четко видеть автомобиль.", "Они могли принять автомобиль за мотоцикл.", "Это может ослепить их.", "Это не повлияет на встречных водителей."], "correct": 1, "expl": "Автомобіль з несправною чи вимкненою однією фарою вночі може бути помилково сприйнятий зустрічними водіями за мотоцикл, що спотворює оцінку відстані й габаритів.", "explSpecific": "Правильно — «Они могли принять автомобиль за мотоцикл». Твердження про кращу видимість чи засліплення суперечать типовому головному ефекту — оманливому враженню про тип транспорту."}, {"num": 768, "text": "Что делать водителю, если его ослепили фары, которые отражаются в зеркале заднего вида автомобиля?", "topic": "Погодні умови та видимість", "options": ["Использовать режим ночного вождения на зеркале заднего вида.", "Включить задние противотуманные фары, чтобы дать сигнал следующему автомобилю выключить фары.", "Выключить и снова включить фары, чтобы напомнить следующему за ним водителю о необходимости включить фары.", "Отрегулировать зеркало таким образом, чтобы оно отражало свет в направлении следующего водителя."], "correct": 0, "expl": "Якщо фари ззаду засліплюють через внутрішнє дзеркало, сучасні дзеркала мають спеціальний нічний режим (антиблиск), який варто увімкнути.", "explSpecific": "Правильно — «Использовать режим ночного вождения на зеркале заднего вида». Спроби «подати сигнал» водієві позаду протитуманними вогнями не вирішують власну проблему засліплення; спрямування відбитого світла на іншого водія — небезпечне рішення."}, {"num": 769, "text": "Что делать водителю, если ночью его слепит свет, отражающийся в его внутреннем зеркале?", "topic": "Погодні умови та видимість", "options": ["Включить задние противотуманные фонари.", "Отрегулировать зеркало таким образом, чтобы оно отражало свет в направлении следующего водителя.", "Включить аварийные световые сигналы.", "Временно отрегулировать угол наклона зеркала."], "correct": 3, "expl": "Якщо світло ззаду засліплює через внутрішнє дзеркало, найпростіший і безпечний спосіб — тимчасово змінити кут нахилу самого дзеркала, щоб відвести відблиск від очей.", "explSpecific": "Правильно — «Временно отрегулировать угол наклона зеркала». Протитуманні вогні чи аварійна сигналізація не мають стосунку до власної засліпленості; спрямування відбитого світла на іншого водія — небезпечне рішення."}, {"num": 770, "text": "Какое освещение должно быть в автомобиле, тракторе или рабочем транспортном средстве во время движения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Только фары, номерной знак и задние отражатели.", "Только фары, стоп-сигналы и указатели поворота.", "Фары и фонарь заднего хода.", "Фары, передние и задние габаритные огни, фонарь заднего номерного знака, красные задние отражатели, стоп-сигналы и указатели поворота."], "correct": 3, "expl": "Під час руху автомобіль, трактор чи робочий транспортний засіб повинен мати повний комплект передбаченого освітлення — не лише фари, а й габарити, підсвітку номера, стоп-сигнали й поворотники.", "explSpecific": "Правильно — «Фары, передние и задние габаритные огни, фонарь заднего номерного знака, красные задние отражатели, стоп-сигналы и указатели поворота» — повний перелік. Скорочені варіанти («тільки фари й номер», «тільки фари й стоп-сигнали», «фари й фонар заднього ходу») пропускають обов'язкові елементи освітлення під час руху."}, {"num": 771, "text": "Какие огни должны быть включены на припаркованном автомобиле, тракторе или рабочем автомобиле ночью на неосвещенной дороге общего пользования?", "topic": "Паркування та зупинка", "options": ["Только задние фонари.", "По крайней мере, один боковой фонарь спереди и сзади на стороне, ближайшей к бордюру.", "По крайней мере, по одному боковому фонарю спереди и сзади на стороне, ближайшей к центру дороги.", "Фары ближнего света."], "correct": 2, "expl": "Припаркований вночі на неосвітленій дорозі транспорт повинен мати щонайменше по одному боковому ліхтарю спереду й ззаду саме з боку, ближчого до центру дороги, — тобто з боку, звідки наближається транспорт.", "explSpecific": "Правильно — «По крайней мере, по одному боковому фонарю спереди и сзади на стороне, ближайшей к центру дороги». Лише задні ліхтарі, ліхтарі з боку бордюра чи фари ближнього світла не відповідають точній вимозі щодо розташування саме з боку центру дороги."}, {"num": 772, "text": "Какая опасность может быть связана с переездом тягача и прицепа через арочный мост?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Стояночный тормоз прицепа может включаться автоматически.", "Прицеп может отсоединиться.", "Подвеска тягача могла сгладить неровности.", "Прицеп может занести."], "correct": 1, "expl": "Переїжджаючи через горбатий (арочний) міст, тягач і причіп можуть зазнати різкого перепаду висоти, через що причіп може відчепитися від тягача.", "explSpecific": "Правильно — «Прицеп может отсоединиться». Автоматичне спрацювання стоянкового гальма причепа, «згладжування нерівностей підвіскою» чи занос причепа — не є типовою небезпекою саме арочного мосту."}, {"num": 773, "text": "Что делать водителю, если автомобиль загорится во время езды по туннелю?", "topic": "Автомагістраль і тунелі", "options": ["Оставаться в автомобиле и позвонить на аварийную станцию, чтобы сообщить о пожаре.", "Немедленно покинуть автомобиль и воспользоваться телефоном экстренной связи на ближайшей аварийной станции.", "Подождите, пока по радио в туннеле не обьявят пожарную тревогу.", "Как можно быстрее доехать до ближайшего аварийного выхода."], "correct": 1, "expl": "У разі загоряння автомобіля під час руху тунелем водій повинен негайно залишити машину і скористатися екстреним телефоном на найближчій аварійній станції.", "explSpecific": "Правильно — «Немедленно покинуть автомобиль и воспользоваться телефоном экстренной связи на ближайшей аварийной станции». Залишання в автомобілі для дзвінка чи очікування оголошення тривоги по радіо — небезпечно зволікають з евакуацією."}, {"num": 774, "text": "Что из следующего должен сделать водитель перед въездом в туннель?", "topic": "Автомагістраль і тунелі", "options": ["Убедиться, что фары ближнего света включены.", "Включить аварийные огни, чтобы предупредить другой транспорт о своем присутствии.", "Использовать только фары ближнего света, если другой транспорт находится в туннеле.", "Убедиться, что фары дальнего света включены."], "correct": 0, "expl": "Перед в'їздом у тунель водій повинен переконатися, що увімкнені фари ближнього світла.", "explSpecific": "Правильно — «Убедиться, что фары ближнего света включены». Аварійні вогні без причини поломки чи умовне ближнє світло — недоречні дії; дальнє світло в тунелі засліплює зустрічний транспорт."}, {"num": 775, "text": "Где следует размещать предупреждающие знаки «начинающий водитель» на автомобилях?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Только спереди.", "Спереди и сзади.", "Только со стороны водителя.", "Только сзади."], "correct": 1, "expl": "Згідно з офіційними правилами дорожнього руху Ірландії, таблички «недосвідчений/учнівський водій» (L або N) мають бути розміщені одночасно спереду і ззаду транспортного засобу, щоб бути помітними для учасників руху з обох напрямків.", "explSpecific": "Правильно — «Спереди и сзади». Розміщення лише спереду, лише ззаду чи лише з боку водія не відповідає офіційній вимозі — таблички повинні бути чітко видимі з обох кінців автомобіля одночасно."}, {"num": 776, "text": "Когда обладатель водительского удостоверения должен размещать на своем автомобиле знаки «начинающий водитель»?", "topic": "Штрафні бали, права та документи", "options": ["Всегда во время движения.", "Во время езды на работу и с работы.", "Только в дневное время.", "При езде по первому водительскому удостоверению."], "correct": 0, "expl": "Знаки «водій-початківець» власник посвідчення повинен розміщувати на автомобілі завжди під час керування, а не лише в окремих ситуаціях.", "explSpecific": "Правильно — «Всегда во время движения». Обмеження лише поїздками на роботу, лише денним часом чи прив'язка до «першого посвідчення» — вигадані умови."}, {"num": 777, "text": "Как водителю рассчитать максимально допустимую массу транспортного средства?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Добавляя собственный вес транспортного средства к разрешенному к перевозке грузу.", "Проверив массу автомобиля без нагрузки.", "Проверив вес груза, который можно перевозить.", "Путем расчета массы автомобиля без нагрузки и веса топлива."], "correct": 0, "expl": "Максимально допустима маса транспортного засобу розраховується як сума власної ваги автомобіля (спорядженої маси) і дозволеної вантажопідйомності, вказаної виробником.", "explSpecific": "Правильно — «Добавляя собственный вес транспортного средства к разрешенному к перевозке грузу». Перевірка лише ваги автомобіля без вантажу чи лише ваги вантажу окремо не дає повної максимально допустимої маси."}, {"num": 778, "text": "Какова максимальная полная масса транспортного средства, которым может управлять владелец водительских прав категории В?", "topic": "Штрафні бали, права та документи", "options": ["3 250 килограмм.", "3 500 килограмм.", "3 000 килограмм.", "3 450 килограмм."], "correct": 1, "expl": "Власник водійських прав категорії B може керувати транспортним засобом максимальною повною масою 3 500 кг.", "explSpecific": "Правильно — «3 500 килограмм». 3 000, 3 250 чи 3 450 кг — неточні значення, які не відповідають встановленій межі категорії B."}, {"num": 779, "text": "Какое максимальное количество пассажиров может перевозиться в транспортном средстве, управляемом обладателем водительских прав категории В", "topic": "Штрафні бали, права та документи", "options": ["9 пассажиров.", "10 пассажиров.", "7 пассажиров.", "8 пассажиров."], "correct": 3, "expl": "Власник посвідчення категорії B може перевозити транспортним засобом максимум 8 пасажирів (не рахуючи водія).", "explSpecific": "Правильно — «8 пассажиров». 7, 9 чи 10 пасажирів перевищують або занижують встановлену межу категорії B."}, {"num": 780, "text": "Когда обладатель водительского удостоверения категории W может перевозить пассажиров?", "topic": "Штрафні бали, права та документи", "options": ["Только если у пассажира также есть водительское удостоверение категории W.", "Только если у пассажира также есть водительское удостоверение категории АМ.", "Только если у пассажира есть водительское удостоверение категории AM и транспортное средство предназначено для перевозки пассажиров.", "Только если у пассажира также есть водительское удостоверение категории W и транспортное средство предназначено для перевозки пассажиров."], "correct": 3, "expl": "Власник посвідчення категорії W (робочий транспорт) може перевозити пасажирів лише за подвійної умови — пасажир також має посвідчення категорії W, і сам транспортний засіб призначений для перевезення пасажирів.", "explSpecific": "Правильно — «Только если у пассажира также есть водительское удостоверение категории W и транспортное средство предназначено для перевозки пассажиров». Варіанти з посвідченням категорії AM або лише з однією з двох умов не відповідають повній вимозі."}, {"num": 781, "text": "Водитель застрял на железнодорожном переезде и не может завести машину. Звонит сигнал о приближающемся поезде. Как водителю следует поступить?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Вытолкнуть автомобиль с переезда.", "Вместе со всеми пассажирами выйти из транспортного средства и позвонить оператору, чтобы предупредить его о необходимости остановить поезда.", "Включить аварийные огни и выйти из транспортного средства", "Оставаться в машине и предупредить приближающийся поезд."], "correct": 1, "expl": "Якщо автомобіль застряг на залізничному переїзді і не заводиться, а поїзд наближається, головний пріоритет — негайно вивести всіх людей з машини на безпечну відстань і повідомити оператора переїзду чи екстрені служби, щоб зупинити поїзд.", "explSpecific": "Правильно — «Вместе со всеми пассажирами выйти из транспортного средства и позвонить оператору, чтобы предупредить его о необходимости остановить поезда». Спроба виштовхнути авто самостійно чи залишатися всередині, попереджаючи поїзд, наражає людей на смертельну небезпеку; лише вмикання аварійних вогнів без виходу з машини недостатньо."}, {"num": 782, "text": "Водитель застрял на неогороженном переезде и не может завести машину. Звонит предупредительный сигнал. Как водителю следует поступить?", "topic": "Паркування та зупинка", "options": ["Вытолкнуть автомобиль с переезда.", "Включить аварийные огни и позвонить оператору по мобильному телефону, чтобы предупредить о поломке.", "Выйти из автомобиля и позвонить оператору чтобы предупредить его о необходимости остановить поезда.", "Оставаться в машине и предупредить приближающийся поезд."], "correct": 2, "expl": "Якщо автомобіль застряг на неогородженому переїзді і не заводиться, а лунає попереджувальний сигнал про поїзд, головний пріоритет — вийти з машини на безпечну відстань і повідомити оператора про потребу зупинити поїзд.", "explSpecific": "Правильно — «Выйти из автомобиля и позвонить оператору чтобы предупредить его о необходимости остановить поезда». Спроба виштовхнути авто самостійно чи залишатися всередині, попереджаючи поїзд, наражає на смертельну небезпеку; лише аварійні вогні без виходу з машини недостатньо."}, {"num": 783, "text": "Каков немедленный эффект лобового столкновения двух автомобилей на скорости?", "topic": "Швидкісний режим", "options": ["Всех людей в каждом автомобиле резко отбрасывает назад.", "Срабатывают только передние ремни безопасности.", "Срабатывают только задние ремни безопасности.", "Всех людей в каждом автомобиле резко выбрасывает вперед."], "correct": 3, "expl": "При лобовому зіткненні двох автомобілів на швидкості пасажирів обох машин за інерцією різко кидає вперед, у напрямку удару.", "explSpecific": "Правильно — «Всех людей в каждом автомобиле резко выбрасывает вперед». Твердження про відкидання назад суперечить фізиці лобового удару; спрацьовування лише передніх чи лише задніх ременів не описує безпосередній фізичний ефект самого зіткнення."}, {"num": 784, "text": "Что нужно делать при замене колеса на дороге общего пользования, чтобы обеспечить собственную безопасность?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Убедиться, что установлена задняя передача, а передние колеса обращены к дороге.", "Убедиться, что установлена первая передача, а передние колеса обращены к дороге.", "Надеть светоотражающую одежду и включить аварийные огни.", "Попросить свидетеля предупредить другой транспорт, подавая ему сигнал стоя в середине дороги."], "correct": 2, "expl": "У більшості таких питань головний принцип один: спочатку стабілізувати керування автомобілем, потім убезпечити себе й інших, і лише тоді усувати наслідки. Наприклад, при заносі коліс потрібно плавно відпустити газ і керувати в напрямку заносу, а не різко гальмувати — різке гальмування або різкий поворот керма посилює втрату зчеплення. При проколі шини чи відмові гальм — тримати кермо міцно, не панікувати і поступово знижувати швидкість, з'їжджаючи на узбіччя. Це пояснює, чому правильна відповідь зазвичай та, що зберігає контроль над автомобілем, а не та, що усуває несправність негайно.", "explSpecific": "Правильна відповідь тут — «Надеть светоотражающую одежду и включить аварийные огни». Інші варіанти в цьому питанні («Убедиться, что установлена задняя передача, а передние колеса обращены к дороге», «Убедиться, что установлена первая передача, а передние колеса обращены к дороге» та «Попросить свидетеля предупредить другой транспорт, подавая ему сигнал стоя в середине дороги») не відповідають цій вимозі й тому неправильні."}, {"num": 785, "text": "Почему опасно позволять детям стоять в пространстве между передними сиденьями автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Если резко нажать на тормоза, их может отбросить назад.", "Они могут отвлекать других водителей, отвлекая их внимание от дороги.", "Им может стать плохо от движения автомобиля.", "Если резко нажать на тормоза, их может выбросить вперед."], "correct": 3, "expl": "Простір між передніми сидіннями не розрахований на утримання людини під час різкого гальмування — при різкому гальмуванні тіло за інерцією продовжує рух вперед і може сильно вдаритися.", "explSpecific": "Правильно — «Если резко нажать на тормоза, их может выбросить вперед». Гальмування, а не рух заднім ходом, викидає тіло ВПЕРЕД за інерцією, тому варіант «назад» невірний; відволікання інших водіїв чи погане самопочуття від руху — не головна причина небезпеки саме в цьому положенні."}, {"num": 786, "text": "Когда детям разрешается высовывать голову через открытый люк автомобиля?", "topic": "Швидкісний режим", "options": ["Если они достигли возраста более 12 лет.", "При движении со скоростью ниже 30 км/ч.", "Детям никогда не разрешается это делать.", "Когда они носят защитные очки."], "correct": 2, "expl": "Дітям заборонено висовувати голову через відкритий люк автомобіля завжди, без винятків за віком, швидкістю чи захисним спорядженням.", "explSpecific": "Правильно — «Детям никогда не разрешается это делать». Винятки за віком понад 12 років, швидкістю нижче 30 км/год чи наявністю захисних окулярів — вигадані, не передбачені правилом послаблення."}, {"num": 787, "text": "Можно ли оставлять детей без присмотра в автомобиле?", "topic": "Паркування та зупинка", "options": ["Только когда автомобиль припаркован на охраняемой автостоянке.", "Только когда автомобиль не припаркован на холме.", "Запрещается оставлять детей в автомобиле без присмотра.", "Только при хорошей вентиляции."], "correct": 2, "expl": "Залишати дітей в автомобілі без нагляду заборонено завжди, незалежно від місця стоянки чи вентиляції.", "explSpecific": "Правильно — «Запрещается оставлять детей в автомобиле без присмотра» — без винятків. Умови про охоронювану стоянку, відсутність ухилу чи гарну вентиляцію — вигадані винятки, яких правило не передбачає."}, {"num": 788, "text": "Когда водителю разрешается перевозить в автомобиле больше пассажиров, чем имеется ремней безопасности?", "topic": "Погодні умови та видимість", "options": ["Никогда не разрешается.", "Когда это не затрудняет видимость водителя.", "При наличии у водителя соответствующей страховки.", "Не разрешается."], "correct": 0, "expl": "Перевозити в автомобілі більше пасажирів, ніж є ременів безпеки, заборонено завжди, без винятків за страховкою чи впливом на огляд водія.", "explSpecific": "Правильно — «Никогда не разрешается». Винятки «якщо не заважає огляду» чи «за наявності страховки» — вигадані, не передбачені законом послаблення."}, {"num": 789, "text": "Когда детям разрешается водить трактор?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Детям не разрешается водить трактор.", "При вождении на очень малых скоростях и без фронтального погрузчика.", "При вождении на очень малых скоростях и без буксировки прицепа.", "В сопровождении водителя, обладающего полноценным водительским удостоверением."], "correct": 0, "expl": "Дітям керувати трактором заборонено за будь-яких умов — це стосується будь-якої дороги і будь-якої швидкості.", "explSpecific": "Правильно — «Детям не разрешается водить трактор» — без винятків. Дозволи «на дуже малій швидкості» без навантажувача чи причепа, або «у супроводі водія з повним посвідченням», — вигадані винятки."}, {"num": 790, "text": "Какая опасность может исходить от вала отбора мощности трактора?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Если его не накрыть, одежда может зацепиться за него.", "Если его не отключить, рулевое управление заблокируется.", "Если он не отключен, аккумулятор разрядится.", "Если его не накрыть, тягач быстро разгонится."], "correct": 0, "expl": "Незахищений вал відбору потужності трактора небезпечний, оскільки одяг людини може зачепитися за нього і затягнути її.", "explSpecific": "Правильно — «Если его не накрыть, одежда может зацепиться за него». Блокування керма, розрядка акумулятора чи раптовий розгін тягача — вигадані, не відповідають реальній небезпеці."}, {"num": 791, "text": "Когда красный флаг является достаточным маркером свисающего сзади груза, выступающего более, чем на один метр?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Только в ночное время.", "Никогда.", "Всегда.", "Только в дневное время."], "correct": 3, "expl": "Червоний прапорець як маркер вантажу, що звисає ззаду більш ніж на метр, достатній лише вдень — у темний час доби потрібне світлове позначення, а не прапорець.", "explSpecific": "Правильно — «Только в дневное время». «Ніколи» і «завжди» — надто категоричні крайнощі; «тільки вночі» прямо суперечить логіці — саме вночі прапорець погано видно і потрібне світло."}, {"num": 792, "text": "Как водителю вписаться в поворот на полностью загруженном автомобиле?", "topic": "Швидкісний режим", "options": ["С той же скоростью, что и при порожнем автомобиле.", "Взяв более крутой изгиб, чем при порожнем автомобиле.", "С более низкой скоростью, чем при порожнем автомобиле.", "С более высокой скоростью, что и при порожнем автомобиле."], "correct": 2, "expl": "На повністю завантаженому автомобілі водій повинен проходити повороти з нижчою швидкістю, ніж на порожньому, оскільки додаткова вага збільшує ризик втрати стійкості.", "explSpecific": "Правильно — «С более низкой скоростью, чем при порожнем автомобиле». Та сама чи вища швидкість, а тим паче різкіший вигин повороту, підвищують ризик перекидання чи заносу завантаженого автомобіля."}, {"num": 793, "text": "Что следует сделать водителю, когда его просят вести автомобиль, который, по его мнению, перегружен?", "topic": "Швидкісний режим", "options": ["Управлять автомобилем только в сопровождении.", "Двигаться с меньшей скоростью, чем обычно.", "Отказаться от управления автомобилем.", "Убедиться, что груз должным образом закреплен."], "correct": 2, "expl": "Якщо водій вважає, що автомобіль перевантажений, найправильніша дія — відмовитися від керування ним, доки проблему не буде усунено.", "explSpecific": "Правильно — «Отказаться от управления автомобилем». Керування лише в супроводі, зниження швидкості чи перевірка кріплення вантажу не усувають основну небезпеку — саму перевантаженість транспортного засобу."}, {"num": 794, "text": "Как буксировка перегруженного прицепа может повлиять на транспортное средство?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Это может ухудшить управляемость и торможение автомобиля.", "Это может улучшить устойчивость на поворотах.", "Это может улучшить расход топлива автомобиля.", "Это может улучшить тормозную способность при спуске с горы."], "correct": 0, "expl": "Буксирування перевантаженого причепа погіршує керованість і гальмування транспортного засобу через надмірне навантаження на зчіпку і гальмівну систему.", "explSpecific": "Правильно — «Это может ухудшить управляемость и торможение автомобиля». Твердження про покращення стійкості на поворотах, витрати палива чи гальмівної здатності на спуску прямо суперечать фізиці перевантаженого причепа."}, {"num": 795, "text": "В какой момент нагрузка на автомобиль сместится с большей вероятностью?", "topic": "Обгін та зміна смуги руху", "options": ["При движении задним ходом.", "При обгоне.", "На поворотах.", "При плавном торможении."], "correct": 2, "expl": "На поворотах відцентрова сила найбільш імовірно зміщує вантаж в автомобілі вбік, на відміну від прямолінійного руху чи плавного гальмування.", "explSpecific": "Правильно — «На поворотах». Рух заднім ходом, обгін чи плавне гальмування самі по собі не створюють такого бокового зміщувального навантаження, як проходження повороту."}, {"num": 796, "text": "Что должен проверить водитель, прикрепляя прицеп к транспортному средству?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Что пружины прицепа хорошо смазаны.", "Что тягово-сцепное устройство надежно закреплено.", "Что в прицепе есть запаска.", "Что груз размещен в передней части прицепа."], "correct": 1, "expl": "Приєднуючи причіп до транспортного засобу, водій повинен насамперед перевірити, що тягово-зчіпний пристрій надійно закріплений.", "explSpecific": "Правильно — «Что тягово-сцепное устройство надежно закреплено». Мастило пружин, наявність запаски чи розміщення вантажу спереду причепа — не є першочерговою перевіркою безпеки самого з'єднання."}, {"num": 797, "text": "Что должен проверить водитель, прикрепляя прицеп к транспортному средству?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Что груз размещен в передней части прицепа.", "Что груз размещен в задней части прицепа.", "Что груз равномерно распределен.", "Что в прицепе есть запаска."], "correct": 2, "expl": "Приєднуючи причіп, водій також повинен перевірити, що вантаж у причепі розподілений рівномірно, щоб не порушити баланс і керованість.", "explSpecific": "Правильно — «Что груз равномерно распределен». Розміщення вантажу лише спереду чи лише ззаду порушує баланс причепа; наявність запаски не стосується перевірки розподілу вантажу."}, {"num": 798, "text": "Что должен сделать водитель, чтобы закрепить тягач перед тем, как отцепить прицеп?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Задействовать стояночный тормоз, выключить зажигание и включить пониженную передачу.", "Опустить опорное колесо, а затем выключить зажигание.", "Отключить электропитание фар прицепа и опустить опорное колесо.", "Задействовать стояночный тормоз, опустить опорное колесо и заглушить двигатель."], "correct": 0, "expl": "Перш ніж відчепити причіп, водій повинен закріпити тягач — задіяти стоянкове гальмо, вимкнути запалювання і увімкнути понижену передачу, щоб унеможливити самовільний рух.", "explSpecific": "Правильно — «Задействовать стояночный тормоз, выключить зажигание и включить пониженную передачу». Опускання опорного колеса чи відключення живлення фар причепа без гальма і передачі не забезпечують надійної фіксації тягача."}, {"num": 799, "text": "Что делать водителю в случае остановки автомобиля в туннеле из-за затора?", "topic": "Автомагістраль і тунелі", "options": ["Заглушить двигатель.", "Держаться ближе к транспортному средству, едущему впереди.", "Применить ручной тормоз и выйти из машины.", "Пройти к ближайшему аварийному выходу."], "correct": 0, "expl": "У разі зупинки автомобіля в тунелі через затор водій повинен заглушити двигун, щоб уникнути накопичення вихлопних газів.", "explSpecific": "Правильно — «Заглушить двигатель». Наближення впритул до транспорту попереду, застосування ручника з виходом з машини без потреби чи прохід до аварійного виходу за звичайного затору — недоречні дії."}, {"num": 800, "text": "Что делать водителю в случае остановки автомобиля в туннеле из-за затора?", "topic": "Автомагістраль і тунелі", "options": ["Посмотреть в зеркало заднего вида и включить аварийные огни, чтобы предупредить идущий сзади транспорт.", "Двигаться ближе к транспортному средству впереди.", "Включить аварийные огни.", "Пройди к ближайшему аварийному выходу."], "correct": 2, "expl": "У разі зупинки автомобіля в тунелі через затор водій повинен увімкнути аварійні вогні, щоб позначити свою присутність для транспорту позаду.", "explSpecific": "Правильно — «Включить аварийные огни». Погляд у дзеркало з увімкненням вогнів — зайве ускладнення; наближення впритул до транспорту попереду чи прохід до аварійного виходу за звичайного затору — недоречні дії."}, {"num": 801, "text": "Когда трактор, скорее всего, перевернется?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["При движении по ровном поверхности.", "При резком повороте.", "При движении вверх по склону.", "При медленном обратном ходе."], "correct": 1, "expl": "Трактор найімовірніше перевернеться під час різкого повороту, коли центр ваги зміщується і виникає ризик втрати стійкості.", "explSpecific": "Правильно — «При резком повороте». Рух рівною поверхнею, підйом угору схилом чи повільний задній хід самі по собі не несуть такого високого ризику перекидання."}, {"num": 802, "text": "Что должен делать водитель при вождении трактора и прицепа при въезде на перекресток с круговым движением, чтобы избежать возможного опрокидывания?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Двигаться на высокой передаче.", "Снизить скорость.", "Задействовать стояночный тормоз.", "Увеличить скорость."], "correct": 1, "expl": "В'їжджаючи на кільцевий перехрестя з трактором і причепом, водій повинен знизити швидкість, щоб уникнути можливого перекидання через зміщення центру ваги.", "explSpecific": "Правильно — «Снизить скорость». Рух на високій передачі, задіяння стоянкового гальма під час руху чи збільшення швидкості — небезпечні дії, що підвищують ризик перекидання."}, {"num": 803, "text": "Что подразумевается под термином «складывание прицепа» (занос)?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Когда прицеп движется быстрее тягача.", "Когда прицеп слишком тяжелый для буксировки тягачом.", "Когда автомобиль скользит по дороге из-за льда или воды.", "Когда домкрат недостаточно силен, чтобы поднять ось."], "correct": 0, "expl": "«Складання» причепа (занос) відбувається, коли причіп рухається швидше за тягач і починає зміщуватися вбік відносно нього.", "explSpecific": "Правильно — «Когда прицеп движется быстрее тягача». Надмірна вага причепа, недостатня сила домкрата чи надмірне мастило пружин не є визначенням цього явища."}, {"num": 804, "text": "Когда может возникнуть складывание (занос) прицепа?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Когда пружины прицепа чрезмерно смазаны.", "При движении боком по склону.", "При движении вверх по склону.", "При попытке резко снизить скорость при движении вниз по склону."], "correct": 3, "expl": "Складання (занос) причепа найчастіше виникає при спробі різко знизити швидкість під час руху вниз по схилу, коли причіп продовжує рух за інерцією.", "explSpecific": "Правильно — «При попытке резко снизить скорость при движении вниз по склону». Надмірне мастило пружин, рух боком по схилу чи підйом угору схилом не є типовими причинами складання причепа."}, {"num": 805, "text": "Водитель тягача, тянущего широкий груз, который закрывает ему обзор сзади, хочет повернуть направо. Как ему следует действовать?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Посмотреть налево и направо, если безопасно, продолжить движение.", "Включить аварийные огни и продолжить движение.", "Попросить кого-нибудь следить за движением позади, пока водитель следит за встречным движением.", "Выйти из машины, посмотреть по сторонам, и если безопасно, продолжить движение."], "correct": 2, "expl": "Якщо широкий вантаж закриває огляд назад, водій тягача, повертаючи праворуч, повинен попросити когось стежити за рухом позаду, поки сам стежить за зустрічним рухом.", "explSpecific": "Правильно — «Попросить кого-нибудь следить за движением позади, пока водитель следит за встречным движением». Погляд лише ліворуч і праворуч, аварійні вогні без спостереження чи вихід з машини — не компенсують відсутність огляду назад під час маневру."}, {"num": 806, "text": "Когда водителю следует использовать габаритные огни автомобиля?", "topic": "Паркування та зупинка", "options": ["При движении в тумане.", "При движении по неосвещенному участку в ночное время.", "Всякий раз при парковке.", "При парковке на неосвещенной дороге."], "correct": 3, "expl": "Габаритні вогні автомобіля обов'язкові саме при стоянці на неосвітленій дорозі вночі, щоб зробити припаркований автомобіль помітним для транспорту, що наближається.", "explSpecific": "Правильно — «При парковке на неосвещенной дороге». Рух у тумані чи по неосвітленій дорозі вночі вимагає повноцінних фар, а не лише габаритів; «завжди при парковці» надто широко — вдень чи на освітленій дорозі габарити не обов'язкові."}, {"num": 807, "text": "Как водитель узнает, что лампа габаритного света вышла из строя?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Включить зажигание, и посмотреть, горят ли лампы.", "Проверив габаритные огни, когда они включены.", "Повернуть руль сначала влево, потом вправо, и посмотреть, горят ли лампы.", "Включить поворотники и посмотреть, горят ли лампы габаритного света."], "correct": 1, "expl": "Щоб перевірити, чи не перегоріла лампа габаритного світла, водій має просто увімкнути габарити і візуально оглянути кожну лампу ззовні.", "explSpecific": "Правильно — «Проверив габаритные огни, когда они включены». Увімкнення запалювання без прямої перевірки самих ламп, повороти керма чи вмикання поворотників не дають прямої відповіді про стан габаритних вогнів."}, {"num": 808, "text": "На что указывает этот знак?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Проверьте уровень масла.", "Неисправность системы рулевого управления с усилением.", "Неисправность выключателя зажигания.", "Неисправность тормозной системы."], "correct": 3, "expl": "Червоний трикутник із знаком оклику всередині кола — універсальний попереджувальний індикатор на панелі приладів, що найчастіше сигналізує про несправність гальмівної системи чи низький рівень гальмівної рідини.", "explSpecific": "Правильно — «Неисправность тормозной системы». «Перевірте рівень масла» позначається окремою піктограмою маслянки; несправності гідропідсилювача керма чи замка запалювання мають власні, geть інші за виглядом індикатори.", "img": "q808.png"}, {"num": 809, "text": "Какое освещение должно быть на двухосном автоприцепе?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Указатели поворота, стоп-сигналы, фонарь заднего номерного знака, красные светоотражатели и задние габаритные огни.", "Мигающие задние габаритные огни.", "Только указатели поворота и фонари заднего номерного знака.", "Только стоп-сигналы и указатели поворота."], "correct": 0, "expl": "Двовісний автопричіп повинен мати повний комплект освітлення: покажчики повороту, стоп-сигнали, ліхтар номерного знака, червоні світловідбивачі та задні габаритні вогні.", "explSpecific": "Правильно — «Указатели поворота, стоп-сигналы, фонарь заднего номерного знака, красные светоотражатели и задние габаритные огни». Лише мигаючі габаритні вогні чи лише окремі елементи не відповідають повному переліку."}, {"num": 810, "text": "Какое освещение должно быть предусмотрено на прицепе тягча в рабочее время?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Разгрузочный фонарь.", "Только стоп-сигналы и указатели поворота.", "Указатели поворота, стоп-сигналы, фонарь заднего номерного знака, красные светоотражатели и задние габаритные огни.", "Только указатели поворота, две белые или желтые фары и фонари заднего номерного знака."], "correct": 2, "expl": "Аналогічно — причіп трактора чи робочого транспорту в робочий час повинен мати той самий повний комплект освітлення.", "explSpecific": "Правильно — «Указатели поворота, стоп-сигналы, фонарь заднего номерного знака, красные светоотражатели и задние габаритные огни». Розвантажувальний ліхтар, лише окремі сигнали чи лише білі/жовті фари не відповідають повному переліку."}, {"num": 811, "text": "При движении по автомагистрали, когда водителю следует использовать аварийные огни?", "topic": "Автомагістраль і тунелі", "options": ["При езде по запасной аварийной полосе.", "При быстром замедлении из-за опасности впереди.", "Когда видит движущихся мотоциклистов.", "При буксировке другого транспортного средства."], "correct": 1, "expl": "На автомагістралі аварійні вогні варто вмикати при різкому уповільненні через небезпеку попереду, щоб попередити транспорт позаду про раптову зміну швидкості.", "explSpecific": "Правильно — «При быстром замедлении из-за опасности впереди». Рух аварійною смугою, спостереження за мотоциклістами чи буксирування іншого транспорту самі по собі не є типовими підставами для аварійних вогнів."}, {"num": 812, "text": "При движении по автомагистрали, когда водителю следует использовать аварийные огни?", "topic": "Автомагістраль і тунелі", "options": ["При езде по запасной аварийной полосе.", "Когда он собирается совершить обгон.", "При поломке транспортного средства.", "При буксировке другого транспортного средства."], "correct": 2, "expl": "На автомагістралі аварійні вогні насамперед використовують у разі поломки транспортного засобу, яка створює перешкоду чи небезпеку.", "explSpecific": "Правильно — «При поломке транспортного средства». Рух аварійною смугою, намір обігнати чи буксирування іншого транспорту самі по собі не є типовими підставами для аварійних вогнів."}, {"num": 813, "text": "Когда водителю следует использовать аварийные огни?", "topic": "Технічні несправності та аварійні ситуації", "options": ["При поломке транспортного средства.", "При движении по узкой дороге.", "Когда видит приближающееся транспортное средство.", "При медленном движении."], "correct": 0, "expl": "Аварійні (сигнальні) вогні призначені попереджати інших учасників руху про раптову небезпеку чи перешкоду — найтиповіший випадок: поломка транспортного засобу.", "explSpecific": "Правильно — «При поломке транспортного средства». Рух вузькою дорогою, наближення зустрічного транспорту чи повільний рух самі по собі не є підставою для аварійних вогнів — для цього є інші сигнали (фари, поворотники)."}, {"num": 814, "text": "Когда водителю следует использовать аварийные огни?", "topic": "Технічні несправності та аварійні ситуації", "options": ["При развороте.", "При повороте на узкую дорогу.", "При поломке, которая препятствует движению другого транспорта.", "При медленном движении."], "correct": 2, "expl": "Аварійні вогні вмикають, коли автомобіль створює несподівану перешкоду для іншого транспорту — наприклад, через поломку просто на проїжджій частині.", "explSpecific": "Правильно — «При поломке, которая препятствует движению другого транспорта». Розворот, поворот на вузьку дорогу чи повільний рух — це звичайні маневри, для яких аварійні вогні не призначені; на них достатньо звичайних поворотників."}, {"num": 815, "text": "Что позволяет сделать водителю использование аварийных огней автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Предупредить других участников дорожного движения о поломке автомобиля.", "Не предупреждать других участников дорожного движения о поломке автомобиля.", "При повороте направо.", "При повороте налево."], "correct": 0, "expl": "Головна функція аварійних вогнів — зробити автомобіль максимально помітним і попередити інших учасників руху про поломку чи іншу небезпеку.", "explSpecific": "Правильно — «Предупредить других участников дорожного движения о поломке автомобиля». Заперечення попередження прямо суперечить самій меті сигналу; прив'язка до конкретного повороту ліворуч чи праворуч не має стосунку до призначення аварійних вогнів."}, {"num": 816, "text": "Какое влияние оказывают аварийные огни на стоп-сигналы?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Они вызывают полное отключение стоп-сигналов.", "Они вызывают мигание стоп-сигналов.", "Они приводят к попеременному миганию левого и правого стоп- сигналов.", "Они не оказывают никакого влияния."], "correct": 3, "expl": "Аварійні вогні працюють через ту саму лампу, що й поворотники, але одночасно з обох боків — вони не мають технічного зв'язку зі стоп-сигналами, які вмикаються окремо при натисканні гальма.", "explSpecific": "Правильно — «Они не оказывают никакого влияния» (на стоп-сигнали). Твердження про відключення чи почергове мигання стоп-сигналів через аварійку — технічно необґрунтовані вигадки; це дві незалежні одна від одної системи освітлення."}, {"num": 817, "text": "На каких колесах вообще работает стояночный (ручной) тормоз?", "topic": "Технічні несправності та аварійні ситуації", "options": ["На задних колесах.", "На заднем правом колесе.", "На всех колесах.", "На передних колесах."], "correct": 0, "expl": "Ручний (стоянковий) гальмо в переважної більшості автомобілів діє механічно через тросик лише на задні колеса, незалежно від приводу самого автомобіля.", "explSpecific": "Правильно — «На задних колесах». Дія лише на одне колесо чи всі чотири одразу — нетипова конструкція для звичайного легкового автомобіля; передні колеса ручним гальмом, як правило, не гальмуються."}, {"num": 818, "text": "В целом, при какой полной массе транспортного средства должны быть установлены тормоза на прицепе?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["850 кг.", "500 кг.", "750 кг.", "900 кг."], "correct": 2, "expl": "Гальма на причепі, як правило, обов'язкові, якщо повна маса транспортного засобу перевищує 750 кг.", "explSpecific": "Правильно — «750 кг». 500, 850 чи 900 кг не відповідають встановленому законом порогу обов'язкового обладнання причепа гальмами."}, {"num": 819, "text": "Каков рекомендуемый способ вождения автомобиля с автоматической коробкой передач?", "topic": "Паркування та зупинка", "options": ["Задействовать акселератор и тормоз правой ногой.", "Задействовать акселератор правой ногой, а тормоз - левой.", "Задействовать акселератор и тормоз левой ногой.", "Использовать ручной тормоз, чтобы остановить автомобиль."], "correct": 0, "expl": "На автомобілі з автоматичною коробкою передач рекомендований спосіб керування — використовувати і газ, і гальмо ПРАВОЮ ногою по черзі, залишаючи ліву ногу вільною.", "explSpecific": "Правильно — «Задействовать акселератор и тормоз правой ногой». Використання лівої ноги для гальма чи обох педалей одночасно може призвести до одночасного натискання газу й гальма; ручний гальмо не замінює ножного під час руху."}, {"num": 820, "text": "Что должен обеспечить водитель при управлении автомобилем с дизельным двигателем в морозную погоду?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Чтобы в багажнике находилась канистра с водой.", "Чтобы в багажнике находилась канистра с дизтопливом.", "Что топливо обработано средством для предотвращения застывания", "Что шины автомобиля накачаны."], "correct": 2, "expl": "У морозну погоду дизельне паливо може загусати чи навіть частково кристалізуватися (парафінування), тому важливо, щоб воно було оброблене спеціальною присадкою проти застигання.", "explSpecific": "Правильно — «Что топливо обработано средством для предотвращения застывания». Канистра з водою чи запасним дизпаливом у багажнику не вирішує проблему застигання палива в самому баку й паливній системі; тиск у шинах не пов'язаний з морозостійкістю дизпалива."}, {"num": 821, "text": "Каковы возможные последствия переполнения двигателя маслом?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Это может привести к повреждению маслонасоса.", "Это может снизить давление масла.", "Это может привести к повреждению масляного фильтра.", "Это может повредить каталитический нейтрализатор."], "correct": 3, "expl": "Переповнення двигуна маслом підвищує тиск у картері, через що масло може потрапити туди, де його бути не повинно, зокрема пошкодивши ущільнення каталітичного нейтралізатора.", "explSpecific": "Правильно — «Это может повредить каталитический нейтрализатор». Пошкодження масляного насоса чи фільтра, а тим паче зниження тиску масла — не типові прямі наслідки саме переповнення, на відміну від ризику для вихлопної системи."}, {"num": 822, "text": "Что делать водителю, если топливная система заблокирована?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Выпустить воздух из топливной системы.", "Слить топливо из топливного фильтра.", "Ослабить топливный насос.", "Затянуть инжекторные трубки."], "correct": 0, "expl": "Якщо паливна система заблокована повітряною пробкою, потрібно випустити повітря з системи (прокачати її), щоб відновити нормальну подачу палива до двигуна.", "explSpecific": "Правильно — «Выпустить воздух из топливной системы». Злив палива з фільтра, послаблення насоса чи затягування трубок інжектора не вирішують саме проблему повітряної пробки."}, {"num": 823, "text": "Разрешено ли водителю использовать легкое (экологичное) дизельное топливо в автомобиле на дорогах общего пользования?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Экологичное дизельное топливо можно использовать в автомобиле только в зимние месяцы.", "Экологичное дизельное топливо запрещается использовать.", "Экологичное дизельное топливо можно использовать в автомобиле только если автомобиль -это такси.", "Экологичное дизельное топливо можно использовать в автомобиле только в летние месяцы."], "correct": 1, "expl": "«Легке» (позашляхове, пофарбоване) дизельне паливо з нижчим оподаткуванням призначене виключно для невиробничого/сільськогосподарського використання і заборонене для автомобілів на дорогах загального користування.", "explSpecific": "Правильно — «Экологичное дизельное топливо запрещается использовать». Дозволи лише взимку, влітку чи для таксі — вигадані винятки, яких не передбачає закон."}, {"num": 824, "text": "Что должен делать водитель, чтобы снизить риск травмы шеи в случае наезда сзади?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Использовать правильно отрегулированный подголовник.", "Убедиться, что на автомобиле есть задний спойлер.", "Убедиться, что в автомобиле есть антиблокировочная система тормозов.", "Использовать правильно отрегулированный ремень безопасности."], "correct": 0, "expl": "Правильно відрегульований підголовник (по висоті й відстані від голови) значно знижує ризик травми шиї (хлистової травми) саме при ударі ззаду, коли голову різко відкидає назад.", "explSpecific": "Правильно — «Использовать правильно отрегулированный подголовник». Задній спойлер чи наявність ABS не мають жодного стосунку до захисту шиї; ремінь безпеки критично важливий загалом, але саме від травми шиї при ударі ЗЗАДУ захищає передусім підголовник."}, {"num": 825, "text": "Когда тягач или рабочий автомобиль необходимо оборудовать зеркалом заднего вида?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Зеркало заднего вида не требуется для тягача или служебного автомобиля.", "Зеркало заднего вида следует устанавливать только при буксировке прицепа длиной более 8 метров.", "Всегда должно быть установлено зеркало заднего вида.", "Зеркало заднего вида следует устанавливать только при буксировке прицепа."], "correct": 2, "expl": "Трактор чи робочий автомобіль завжди повинен бути обладнаний дзеркалом заднього виду, незалежно від того, чи буксирує він причіп.", "explSpecific": "Правильно — «Всегда должно быть установлено зеркало заднего вида». Твердження про відсутність потреби в дзеркалі чи прив'язку вимоги лише до буксирування причепа (довжиною понад 8 метрів) — не відповідають обов'язковій, постійній вимозі."}, {"num": 826, "text": "Какова минимальная допустимая глубина протектора шин на автомобилях?", "topic": "Загальні правила та поведінка на дорозі", "options": ["2,6 миллиметра.", "1 миллиметра.", "1,6 миллиметра.", "0,6 миллиметра."], "correct": 2, "expl": "Законодавчо встановлена мінімальна глибина протектора шини для легкових автомобілів в Ірландії та ЄС становить 1,6 міліметра по всій ширині протектора.", "explSpecific": "Правильно — «1,6 миллиметра» — офіційний встановлений мінімум. Інші числа не відповідають законодавчо закріпленому значенню."}, {"num": 827, "text": "На что указывает индекс нагрузки шины?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Максимальная нагрузка автомобиля.", "Максимальное давление воздуха в шине.", "Максимальная нагрузка на ось.", "Максимальная нагрузка, которую может выдержать шина."], "correct": 3, "expl": "Індекс навантаження шини — це числовий код на боковині, що визначає максимальну вагу, яку може безпечно витримати одна шина за нормальних умов.", "explSpecific": "Правильно — «Максимальная нагрузка, которую может выдержать шина». Максимальна вага автомобіля в цілому чи навантаження на вісь — це geть інші, ширші характеристики транспортного засобу, а не окремої шини; максимальний тиск повітря позначається окремим числом на боковині."}, {"num": 828, "text": "При каких обстоятельствах на транспортном средстве могут быть установлены как диагональные, так и радиальные шины?", "topic": "Погодні умови та видимість", "options": ["При перевозке тяжелых грузов.", "При буксировке прицепа по снегу.", "При движении по скользкой дороге.", "Когда шина каждого типа устанавливается на разные оси."], "correct": 3, "expl": "Змішувати діагональні (bias-ply) і радіальні шини дозволяється лише тоді, коли кожен тип встановлений на СВОЮ окрему вісь, а не довільно на одній осі.", "explSpecific": "Правильно — «Когда шина каждого типа устанавливается на разные оси». Перевезення важких вантажів, буксирування причепа по снігу чи рух слизькою дорогою самі по собі не дозволяють змішування типів шин."}, {"num": 829, "text": "Каков эффект упора ноги на педаль сцепления?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Износ тормозных колодок.", "Неисправность двигателя.", "Муфта сцепления изнашивается быстрее, чем обычно.", "Это способствует повышенному износу сцепления."], "correct": 2, "expl": "Тримання ноги постійно на педалі зчеплення (навіть без натискання) створює тертя вижимного підшипника з диском зчеплення, прискорюючи його знос.", "explSpecific": "Правильно — «Муфта сцепления изнашивается быстрее, чем обычно». Знос гальмівних колодок чи несправність двигуна не пов'язані з положенням лівої ноги на педалі зчеплення; повторення про «підвищений знос зчеплення» в іншому варіанті — просто менш точне формулювання того ж самого висновку."}, {"num": 830, "text": "Для чего нужны боковые брусья безопасности?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Для защиты пассажиров при ударах сверху", "Для защиты пассажиров при ударе сбоку.", "Для обеспечения прочности двери при эксплуатации", "Для защиты кузова от деформации при падении объектов на крышу."], "correct": 1, "expl": "Бокові брусья безпеки (side impact bars) вбудовані в двері саме для захисту пасажирів під час бокового удару — найнебезпечнішого типу зіткнення через мінімальну деформаційну зону збоку.", "explSpecific": "Правильно — «Для защиты пассажиров при ударе сбоку». Захист від ударів зверху, падаючих об'єктів чи забезпечення міцності дверей при експлуатації — не є основним призначенням цих брусів."}, {"num": 831, "text": "Когда резервуар для жидкости заполнен до отметки, как водитель может проверить правильность работы усиленного рулевого управления?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Повернуть рулевое колесо из упора в упор при выключенном двигателе.", "Повернуть рулевое колесо из упора в упор, нажимая на педаль сцепления.", "Повернуть рулевое колесо из упора в упор при задействованном ручном тормозе.", "Повернуть рулевое колесо из упора в упор при работающем двигателе."], "correct": 3, "expl": "Щоб перевірити роботу гідропідсилювача керма, кермо повертають з упору в упор при УВІМКНЕНОМУ двигуні — саме тоді насос гідропідсилювача працює і можна оцінити його справність.", "explSpecific": "Правильно — «Повернуть рулевое колесо из упора в упор при работающем двигателе». При вимкненому двигуні гідропідсилювач не працює, тому перевірка на заглушеному двигуні (з натиснутим зчепленням чи увімкненим ручним гальмом) не покаже реальну роботу системи."}, {"num": 832, "text": "Что должен делать водитель транспортного средства с усиленным рулевым управлением (PAS), если рулевое управление затрудняется во время движения?", "topic": "Паркування та зупинка", "options": ["Остановиться, проверить уровень жидкости и при необходимости долить.", "Перевести автомобиль в нейтральную передачу и повернуть руль.", "Сбросить скорость и повернуть руль.", "Остановиться, проверить уровень масла, и при необходимости, долить."], "correct": 0, "expl": "Якщо кермо з гідропідсилювачем стає важким під час руху, водій повинен зупинитися, перевірити рівень рідини гідропідсилювача і за потреби долити.", "explSpecific": "Правильно — «Остановиться, проверить уровень жидкости и при необходимости долить». Продовження руху на нейтральній передачі чи просто зі зниженою швидкістю не усуває причину — нестачу рідини в системі."}, {"num": 833, "text": "К чему приводит неправильно отрегулированное сиденье водителя?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Это может помешать водителю использовать элемент управления.", "Позволяет улучшить способность водителя задействовать сцепление.", "Позволяет водителю больше расслабиться при поездке на дальние расстояния.", "Обеспечивает водителю лучший обзор в зеркало заднего вида."], "correct": 0, "expl": "Неправильно відрегульоване сидіння водія може заважати вільно й повністю користуватися педалями, кермом чи важелем передач, знижуючи безпеку керування.", "explSpecific": "Правильно — «Это может помешать водителю использовать элемент управления». Твердження про покращення можливості задіяти зчеплення, більший комфорт чи кращий огляд у дзеркало прямо суперечать реальному негативному ефекту."}, {"num": 834, "text": "Водитель замечает, что щетки стеклоочистителя изношены. Как ему следует действовать?", "topic": "Погодні умови та видимість", "options": ["Опустить стекло и медленно двигаться.", "Как можно скорее заменить щетки.", "Использовать систему омывателя ветрового стекла во время дождя.", "Протереть ветровое стекло газетой."], "correct": 1, "expl": "Зношені щітки склоочисника гірше очищують лобове скло, знижуючи видимість під час дощу, тому їх варто замінити якнайшвидше, а не шукати альтернативні способи очищення.", "explSpecific": "Правильно — «Как можно скорее заменить щетки». Відкрите вікно, омивач без заміни щіток чи протирання газетою — тимчасові й неефективні замінники справних щіток."}, {"num": 835, "text": "Что делать, если щетки стеклоочистителя не очищают ветровое стекло?", "topic": "Швидкісний режим", "options": ["Нанести пару капель масла на обе щетки стеклоочистителя.", "Согнуть рычаг стеклоочистителя, чтобы усилить давление на ветровое стекло.", "Как можно скорее заменить щетки стеклоочистителя.", "Переключить рычаг управления стеклоочистителя с высокой скорости на низкую скорость несколько раз."], "correct": 2, "expl": "Якщо щітки склоочисника не очищують лобове скло, найправильніше рішення — якнайшвидше замінити самі щітки.", "explSpecific": "Правильно — «Как можно скорее заменить щетки стеклоочистителя». Мастило на щітках чи згинання важеля для посилення тиску — неправильні й тимчасові рішення; перемикання швидкості щіток кілька разів не усуває причину — знос гумки."}, {"num": 836, "text": "Что делать водителю перед въездом в туннель, чтобы улучшить видимость?", "topic": "Автомагістраль і тунелі", "options": ["Надеть солнцезащитные очки, чтобы избежать спящего света.", "Отпустить козырек, чтобы избежать бликов от верхнего освещения.", "Держаться ближе к транспортному средству, едущему впереди.", "Снять солнцезащитные очки."], "correct": 3, "expl": "Перед в'їздом у тунель водій повинен зняти сонцезахисні окуляри, щоб покращити видимість у темнішому просторі тунелю.", "explSpecific": "Правильно — «Снять солнцезащитные очки». Надягання окулярів «щоб уникнути сонного світла» прямо суперечить потребі; опускання козирка від верхнього освітлення чи наближення впритул до транспорту попереду — недоречні дії."}, {"num": 837, "text": "Что делать водителю перед тем, как проехать через туннель?", "topic": "Автомагістраль і тунелі", "options": ["Убедиться, что у него достаточно топлива.", "Отключить глобальную систему позиционирования (GPS).", "Включить только габаритные огни.", "Зарегистрироваться на первой туннельной станции."], "correct": 0, "expl": "Перед проїздом через тунель водій повинен переконатися, що має достатньо палива, оскільки зупинка чи розворот всередині тунелю вкрай небажані й небезпечні.", "explSpecific": "Правильно — «Убедиться, что у него достаточно топлива». Вимкнення GPS, використання лише габаритних вогнів чи «реєстрація на першій тунельній станції» — вигадані дії, не пов'язані з реальною підготовкою до проїзду тунелем."}, {"num": 838, "text": "Какова максимальная разрешенная масса (MAM) автомобиля, которым может управлять владелец водительских прав категории В?", "topic": "Штрафні бали, права та документи", "options": ["3 500 килограмм.", "4 000 килограмм.", "3 750 килограмм.", "3 000 килограмм."], "correct": 0, "expl": "Той самий ліміт — максимально дозволена маса (MAM) автомобіля для власника посвідчення категорії B становить 3 500 кг.", "explSpecific": "Правильно — «3 500 килограмм». 3 000, 3 750 чи 4 000 кг — неточні значення, які не відповідають встановленій межі категорії B."}, {"num": 839, "text": "После сдачи экзамена по вождению, разрешено ли ученику водить автомобиль без сопровождения в качестве обладателя квалификационного удостоверения?", "topic": "Штрафні бали, права та документи", "options": ["Да, учащемуся водителю разрешается водить автомобиль без сопровождения по квалификационному удостоверению, если у него отображается знак «N».", "Нет, учащемуся водителю не разрешается водить автомобиль без сопровождения по квалификационному удостоверению, если на его автомобиле не будет установлен знак «начинающий водитель».", "Да, учащемуся водителю разрешается водить автомобиль без сопровождения по квалификационному удостоверению, если он уведомит свою страховую компанию.", "Нет, учащемуся водителю не разрешается водить автомобиль без сопровождения до тех пор, пока он не получит полноценное водительское удостоверение соответствующей категории."], "correct": 3, "expl": "Кваліфікаційне посвідчення (після складання іспиту, але до повного посвідчення) не дає права їздити без супроводу — це право з'являється лише з повним посвідченням відповідної категорії.", "explSpecific": "Правильно — «Нет, учащемуся водителю не разрешается водить автомобиль без сопровождения до тех пор, пока он не получит полноценное водительское удостоверение соответствующей категории». Знак «N», повідомлення страхової компанії — не скасовують обов'язкової вимоги супроводу."}, {"num": 840, "text": "Учащийся водитель, уличенный в вождении без сопровождения, получает минимальное количество штрафных баллов?", "topic": "Штрафні бали, права та документи", "options": ["3 штрафных балла.", "2 штрафных балла.", "4 штрафных балла.", "5 штрафных балла."], "correct": 1, "expl": "Учень, викритий у керуванні без супроводу, отримує мінімум 2 штрафних бали.", "explSpecific": "Правильно — «2 штрафных балла». 3, 4 чи 5 балів не відповідають встановленому мінімуму за це порушення."}, {"num": 841, "text": "Что делать водителю, если автомобиль сломался на автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Воспользоваться придорожным телефоном, чтобы связаться с Гарда, и никогда не пытаться ремонтировать автомобиль самостоятельно.", "Поместить красный предупреждающий треугольник на автомагистрали, чтобы предупредить других водителей.", "Попросить пассажира встать на дороге, чтобы предупредить других участников движения.", "Включить дальний свет фар, чтобы предупредить других водителей."], "correct": 0, "expl": "Якщо автомобіль зламався на автомагістралі, водій повинен скористатися придорожнім телефоном для зв'язку з поліцією і не намагатися самостійно ремонтувати автомобіль на небезпечній ділянці.", "explSpecific": "Правильно — «Воспользоваться придорожным телефоном, чтобы связаться с Гарда, и никогда не пытаться ремонтировать автомобиль самостоятельно». Розміщення трикутника прямо на автомагістралі чи прохання пасажира стояти на дорозі наражають людей на смертельну небезпеку."}, {"num": 842, "text": "Что мог бы сделать водитель, чтобы избежать чрезмерного загрязнения выхлопными газами от своего автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Управлять дизельным двигателем.", "Регулярно менять воздушные фильтры автомобиля.", "Двигаться на более высоких скоростях, чтобы сократить время, затрачиваемое на дорогу.", "Используйте присадку к топливу для повышения октанового числа топлива."], "correct": 1, "expl": "Регулярна заміна повітряного фільтра забезпечує правильне співвідношення повітря й палива при згорянні, зменшуючи шкідливі викиди з вихлопної труби.", "explSpecific": "Правильно — «Регулярно менять воздушные фильтры автомобиля». Використання дизельного двигуна саме по собі не зменшує забруднення; рух на вищих швидкостях чи присадки для підвищення октанового числа не є ефективними способами зниження викидів."}, {"num": 843, "text": "Насколько часто нужно проводить техническое обслуживание автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Согласно рекомендации производителя.", "Каждые 30 месяцев.", "Раз в год.", "Каждые 30 000 километров."], "correct": 0, "expl": "Періодичність технічного обслуговування автомобіля визначає виробник у сервісній книжці — вона залежить від конкретної моделі, а не від універсального фіксованого інтервалу.", "explSpecific": "Правильно — «Согласно рекомендации производителя». Фіксовані інтервали можуть не відповідати реальним вимогам конкретного автомобіля, вказаним виробником."}, {"num": 844, "text": "Какова цель каталитического нейтрализатора?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Ограничить уровень шума от выхлопных газов только на автомобилях с дизельным двигателем.", "Снизить вредные выбросы выхлопных газов.", "Позволить восстановить выхлопную систему.", "Ограничить уровень шума выхлопной системы только на автомобилях с бензиновым двигателем."], "correct": 1, "expl": "Той самий каталітичний нейтралізатор, що вже описувався раніше в цій темі, знижує шкідливі викиди вихлопних газів незалежно від типу двигуна.", "explSpecific": "Правильно — «Снизить вредные выбросы выхлопных газов». Обмеження шуму окремо для дизельних чи бензинових двигунів — вигадане звуження; «відновити вихлопну систему» не є функцією каталізатора."}, {"num": 845, "text": "Какой тип шума может создать быстрый поворот?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Визг тормозов.", "Визг шин.", "Вспышка пламени.", "Возгорание двигателя."], "correct": 1, "expl": "Швидкий, різкий поворот керма змушує шини ковзати боком по асфальту замість чистого кочення, що і породжує характерний вищальний звук.", "explSpecific": "Правильно — «Визг шин». Візг гальм виникає саме при натисканні педалі гальма, а не при повороті; спалах полум'я чи займання двигуна — geть інші, набагато рідкісніші й серйозніші події, не пов'язані зі звичайним різким поворотом."}, {"num": 846, "text": "Что должен сделать водитель прежде чем выйти из автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Прежде чем открыть дверь необходимо посмотреть в боковое зеркало заднего вида, а также посмотреть назад.", "Приоткрыть дверь и посмотреть назад.", "Включить аварийные огни.", "Прежде чем открыть дверь, посмотреть во внутреннее зеркало заднего вида."], "correct": 0, "expl": "Перш ніж відчинити двері, водій повинен подивитися і в бокове дзеркало, і безпосередньо назад через плече, щоб не зачепити транспорт чи велосипедиста, який наближається ззаду.", "explSpecific": "Правильно — «Прежде чем открыть дверь необходимо посмотреть в боковое зеркало заднего вида, а также посмотреть назад» — подвійна перевірка. Лише одне дзеркало (внутрішнє) чи привідкриття дверей із поглядом назад без використання дзеркал не забезпечують достатнього огляду сліпих зон."}, {"num": 847, "text": "Что должен сделать водитель прежде чем выйти из автомобиля?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Подать сзади впереди идущему транспорту.", "Приоткрыть дверь и посмотреть назад.", "Прежде чем открывать дверь следует оглянуться, чтобы убедиться, что нет приближающегося транспорта и пешеходов.", "Прежде чем открыть дверь, посмотреть во внутреннее зеркало заднего вида."], "correct": 2, "expl": "Перш ніж вийти з автомобіля, водій повинен обов'язково оглянутися, щоб переконатися у відсутності транспорту чи пішоходів, які наближаються.", "explSpecific": "Правильно — «Прежде чем открывать дверь следует оглянуться, чтобы убедиться, что нет приближающегося транспорта и пешеходов». Подача сигналу заднього транспорту чи лише внутрішнє дзеркало — недостатні заходи безпеки."}, {"num": 848, "text": "Как водителю следует обезопасить свой автомобиль перед тем, как выйти из него?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Задействовать стояночный тормоз, заглушить двигатель и включить пониженную передачу.", "Отвести колеса от обочины и заглушить двигатель.", "Отвести колеса к бордюру и заглушить двигатель.", "Выбрать пониженную передачу и заглушить двигатель."], "correct": 0, "expl": "Залишаючи автомобіль без нагляду, водій повинен обов'язково задіяти стоянковий гальмо і заглушити двигун, щоб унеможливити самовільний рух авто.", "explSpecific": "Правильно — «Задействовать стояночный тормоз, заглушить двигатель и включить пониженную передачу». Відведення коліс від чи до бордюру без гальма й вимкненого двигуна недостатньо; сама лише знижена передача без стоянкового гальма не гарантує нерухомості авто на рівній ділянці."}, {"num": 849, "text": "Как водителю позволить пассажирам выйти из автомобиля на загруженной дороге?", "topic": "Обгін та зміна смуги руху", "options": ["Остановиться и дать им выйти на ближайшую к тротуару сторону.", "Перед тем, как позволить пассажирам выйти, подать сигнал следующему за ним транспорту о возможности совершить обгон.", "Остановиться и убедить их выйти как можно быстрее.", "Остановиться и позволить им выйти с любой стороны автомобиля, с которой они сидят."], "correct": 0, "expl": "Висаджуючи пасажирів на завантаженій дорозі, водій повинен зупинитися і дозволити їм вийти саме з боку, найближчого до тротуару, подалі від транспортного потоку.", "explSpecific": "Правильно — «Остановиться и дать им выйти на ближайшую к тротуару сторону». Сигналізація про обгін перед висадкою не є пріоритетним кроком; дозвіл виходити з будь-якого боку підвищує ризик для пасажирів."}, {"num": 850, "text": "Какая фиксированная сумма и штрафы взимаются с учащегося водителя, управляющего автомобилем без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["Штраф в размере 80 евро и 3 штрафных пункта.", "Штраф в размере 100 евро и 2 штрафных пунктов.", "Штраф в размере 80 евро и 2 штрафных пунктов.", "Штраф в размере 60 евро и 5 штрафных пунктов."], "correct": 2, "expl": "Фіксований штраф для учня, який керує автомобілем без супроводу, становить 80 євро та 2 штрафних пункти.", "explSpecific": "Правильно — «Штраф в размере 80 евро и 2 штрафных пунктов». Суми 60 чи 100 євро або інша кількість пунктів (3 чи 5) не відповідають встановленим фіксованим санкціям."}, {"num": 851, "text": "Если ремни безопасности предусмотрены в автомобиле, когда взрослые пассажиры должны их использовать?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Только при поездках за пределы населенных пунктов.", "Всегда.", "Только при поездках более 10 километров.", "Только в дальних поездках."], "correct": 1, "expl": "Якщо в автомобілі передбачені ремені безпеки, дорослі пасажири зобов'язані пристібатися завжди, незалежно від відстані чи маршруту поїздки.", "explSpecific": "Правильно — «Всегда». Обмеження обов'язку лише дальніми поїздками, поїздками за межі населених пунктів чи поїздками понад 10 км — вигадані винятки, яких не передбачає закон."}, {"num": 852, "text": "Может ли обучающийся водитель водить автомобиль без сопровождения, если владеет третьим или последующим водительским удостоверением?", "topic": "Штрафні бали, права та документи", "options": ["Нет, если только он не установил знак «L» на передней и задней части автомобиля.", "Нет, если только он не установил знак «N» на передней и задней части автомобиля.", "Нет, они не могут водить автомобиль без сопровождения по любому удостоверению учащегося водителя.", "Да, но не на автомагистралях."], "correct": 2, "expl": "Незалежно від того, яке за рахунком посвідчення учня (третє чи наступне), правило незмінне — керування без супроводу заборонено завжди.", "explSpecific": "Правильно — «Нет, они не могут водить автомобиль без сопровождения по любому удостоверению учащегося водителя». Знаки «L» чи «N» не скасовують саму заборону; виняток лише для автомагістралей також не передбачений — учням заборонено там їздити взагалі."}, {"num": 853, "text": "Что должен сделать водитель, чтобы обезопасить автомобиль перед тем, как выйти из него.", "topic": "Технічні несправності та аварійні ситуації", "options": ["Оставить двигатель работать с включенным тормозом-замедлителем.", "Задействовать стояночный тормоз и заглушить двигатель.", "Задействовать тормоз=замедлитель и заглушить двигатель.", "Оставить двигатель работать с задействованным стояночным тормозом."], "correct": 1, "expl": "Той самий базовий принцип безпеки перед виходом з автомобіля — задіяти стоянковий гальмо і заглушити двигун.", "explSpecific": "Правильно — «Задействовать стояночный тормоз и заглушить двигатель». Залишення працюючого двигуна з будь-яким гальмом-уповільнювачем чи без стоянкового гальма небезпечне й не гарантує нерухомості автомобіля."}, {"num": 854, "text": "Кто несет ответственность за то, чтобы пассажир старше 17 лет использовал ремень безопасности во время поездки в автомобиле?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Водитель, если пассажир находится на переднем сиденье.", "Только пассажир.", "Водитель и пассажир.", "Только водитель."], "correct": 1, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Только пассажир». Інші варіанти в цьому питанні («Водитель, если пассажир находится на переднем сиденье», «Водитель и пассажир» та «Только водитель») не відповідають цій вимозі й тому неправильні."}, {"num": 855, "text": "Кто несет ответственность за то, чтобы пассажир младше 17 лет использовал ремень безопасности во время поездки в автомобиле?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Только водитель.", "Водитель, но только если пассажир находится на переднем сиденье.", "Только пассажир.", "Родители пассажира."], "correct": 0, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Только водитель». Інші варіанти в цьому питанні («Водитель, но только если пассажир находится на переднем сиденье», «Только пассажир» та «Родители пассажира») не відповідають цій вимозі й тому неправильні."}, {"num": 856, "text": "Кто отвечает за использование детской удерживающий системы в автомобиле?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Ребенок, если он старше 12 лет.", "Любой взрослый пассажир.", "Только водитель.", "Только родители ребенка."], "correct": 2, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Только водитель». Інші варіанти в цьому питанні («Ребенок, если он старше 12 лет», «Любой взрослый пассажир» та «Только родители ребенка») не відповідають цій вимозі й тому неправильні."}, {"num": 857, "text": "В целом, как обеспечить безопасность детей до 3 лет в автомобиле?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Дети всегда должны быть закреплены в правильном детском кресле.", "Они всегда должны сидеть на заднем пассажирском сиденье.", "Их всегда следует размещать на сиденье переднего пассажира с пристегнутым ремнем безопасности.", "Дети всегда должны сидеть на коленях у взрослого человека."], "correct": 0, "expl": "Дітей до 3 років в автомобілі завжди потрібно перевозити в правильно підібраному й встановленому дитячому утримувальному кріслі, відповідному до їхньої ваги й віку.", "explSpecific": "Правильно — «Дети всегда должны быть закреплены в правильном детском кресле». Розміщення на задньому сидінні без крісла, на передньому з дорослим ременем чи на колінах дорослого — небезпечні альтернативи."}, {"num": 858, "text": "Можно ли перевозить ребенка в возрасте до 3 лет не пристегнутым на переднем пассажирском сиденье автомобиля?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Нет, если ребенок не использует детское сидение.", "Да, при условии, что младенца надежно удерживает взрослый.", "Да, но только если на автомобиле установлены активные подушки безопасности.", "Нет, ребенок всегда должен быть зафиксирован в соответствующем детском кресле."], "correct": 3, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Нет, ребенок всегда должен быть зафиксирован в соответствующем детском кресле». Інші варіанти в цьому питанні («Нет, если ребенок не использует детское сидение», «Да, при условии, что младенца надежно удерживает взрослый» та «Да, но только если на автомобиле установлены активные подушки безопасности») не відповідають цій вимозі й тому неправильні."}, {"num": 859, "text": "Как следует закрепить детскую удерживающую систему в автомобиле?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Ее следует устанавливать в соответствии с инструкциями производителя.", "На расстоянии 50 см от окна.", "Рядом с сиденьем водителя.", "За водительским сиденьем."], "correct": 0, "expl": "Ці питання перевіряють базовий принцип безпечного водіння: передбачати дії інших учасників руху й лишати запас часу та простору для реакції. Правильна відповідь зазвичай та, що зменшує ризик або невизначеність (більша дистанція, менша швидкість, більша увага), а не та, що просто найшвидша чи найзручніша для водія. Ірландські правила приділяють велику увагу відповідальності водія за стан транспортного засобу та за передбачувану, а не реактивну манеру керування.", "explSpecific": "Правильна відповідь тут — «Ее следует устанавливать в соответствии с инструкциями производителя». Інші варіанти в цьому питанні («На расстоянии 50 см от окна», «Рядом с сиденьем водителя» та «За водительским сиденьем») не відповідають цій вимозі й тому неправильні."}, {"num": 860, "text": "Что делать водителю, в случае прокола передней шины во время движения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Немедленно задействовать ручной тормоз.", "Отпустить руль.", "Крепко схватиться за руль.", "Быстро и резко затормозить."], "correct": 2, "expl": "У разі проколу передньої шини під час руху головне правило — міцно тримати кермо обома руками, щоб автомобіль не потягнуло вбік неконтрольовано.", "explSpecific": "Правильно — «Крепко схватиться за руль». Негайне застосування ручного гальма чи різке гальмування можуть заблокувати колеса й спричинити занос; відпускання керма дає автомобілю некеровано з'їхати вбік."}, {"num": 861, "text": "Что делать водителю, если у него на дороге лопнуло колесо.", "topic": "Паркування та зупинка", "options": ["Немедленно задействовать стояночный тормоз, чтобы остановить автомобиль.", "Продолжать ехать, пока не доберетесь до гаража.", "Выключить зажигание двигателя, чтобы автомобиль остановился.", "Осторожно нажать на педаль тормоза и остановить автомобиль."], "correct": 3, "expl": "Якщо на ходу лопнуло колесо, водій повинен обережно натиснути на педаль гальма і плавно зупинити автомобіль, уникаючи різких дій.", "explSpecific": "Правильно — «Осторожно нажать на педаль тормоза и остановить автомобиль». Негайне застосування ручника чи вимкнення запалювання можуть заблокувати колеса й спричинити занос; продовження руху до гаража на пошкодженому колесі шкідливе."}, {"num": 862, "text": "Как понять, что лопнула передняя шина?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Рулевое колесо уведет в сторону.", "Колеса заблокируются и перестанут вращаться.", "Антиблокировочная система тормозов отключится автоматически.", "Рулевое колесо останется в прямом положении."], "correct": 0, "expl": "Коли лопається передня шина, втрата тиску з одного боку передньої осі різко змінює опір коченню, через що кермо різко тягне вбік — це і є головна ознака.", "explSpecific": "Правильно — «Рулевое колесо уведет в сторону». Блокування коліс чи автоматичне відключення ABS не є типовим наслідком саме проколу; незмінне пряме положення керма прямо суперечить фізиці різкої втрати тиску в одній шині."}, {"num": 863, "text": "Как понять, что лопнуло заднее колесо?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Рулевое колесо уведет вправо.", "Ручной тормоз включиться автоматически.", "Это может привести к блокировке колес и прекращению вращения.", "Это может привести к раскачиванию автомобиля из стороны в сторону."], "correct": 3, "expl": "Коли лопається заднє колесо, автомобіль втрачає стабільність задньої осі, через що його може почати розгойдувати з боку в бік, на відміну від чіткого відхилення керма при проколі переднього колеса.", "explSpecific": "Правильно — «Это может привести к раскачиванию автомобиля из стороны в сторону». Кермо реагує сильніше саме на передні шини, тому «уведет вправо» менш точно описує наслідок проколу заднього колеса; автоматичне залучення ручного гальма чи блокування коліс — вигадані сценарії."}, {"num": 864, "text": "Как водителю следует задействовать тормоза в аварийной ситуации, если автомобиль оснащен антиблокировочной тормозной системой ABS.", "topic": "Технічні несправності та аварійні ситуації", "options": ["Слегка нажимать на педаль тормоза.", "Сильно нажимать и удерживать педаль тормоза.", "Медленно нажимать и отпускать педаль тормоза.", "Нажимать и отпускать тормоз через короткое промежутки времени."], "correct": 1, "expl": "На автомобілі з ABS в екстреній ситуації потрібно сильно натиснути і УТРИМУВАТИ педаль гальма — система сама швидко пульсує тиск у гальмівному контурі, не даючи колесам заблокуватися.", "explSpecific": "Правильно — «Сильно нажимать и удерживать педаль тормоза». Слабке натискання не використовує повний потенціал гальм; ручне переривчасте натискання-відпускання («помпаж») було правильним для авто БЕЗ ABS, але для системи з ABS воно лише заважає її роботі."}, {"num": 865, "text": "Что делать водителю, в случае заноса четырех колес автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Повернуть рулевое колесо в обратном направлении и задействовать ручной тормоз.", "Повернуть рулевое колесо в обратном направлении, чтобы улучшить сцепление шины с дорогой.", "Повернуть рулевое колесо в том же направлении, что и занос, и ослабьте педаль акселератора.", "Повернуть рулевое колесо в том же направлении, что и занос, и задействовать ручной тормоз."], "correct": 2, "expl": "У разі заносу всіх чотирьох коліс одразу класична техніка — повернути кермо в напрямку заносу (щоб вирівняти передні колеса за напрямком руху) і плавно відпустити газ, не гальмуючи різко.", "explSpecific": "Правильно — «Повернуть рулевое колесо в том же направлении, что и занос, и ослабьте педаль акселератора». Поворот керма У ПРОТИЛЕЖНОМУ напрямку лише посилить занос; застосування ручного гальма під час заносу всіх коліс різко підвищує ризик перекидання автомобіля."}, {"num": 866, "text": "Что делать водителю в случае заноса передних колес автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Отпустите акселератор.", "Нажать на ножной тормоз.", "Продолжать ускоряться.", "Задействовать ручной тормоз."], "correct": 0, "expl": "При заносі саме передніх коліс (втраті керованості на повороті) головна дія — плавно відпустити газ, дозволяючи шинам відновити зчеплення з дорогою.", "explSpecific": "Правильно — «Отпустите акселератор». Натискання на ножний чи ручний гальмо під час заносу передніх коліс може ще більше погіршити ситуацію; продовження прискорення прямо протилежне правильній реакції."}, {"num": 867, "text": "Что делать водителю в случае заноса задних колес автомобиля?", "topic": "Паркування та зупинка", "options": ["Повернуть рулевое колесо в направлении задних колес.", "Нажать ножной тормоз, чтобы остановить автомобиль.", "Задействовать стояночный тормоз, чтобы остановить автомобиль.", "Повернуть рулевое колесо в направлении передних колес"], "correct": 0, "expl": "У разі заносу задніх коліс (машину «заносить хвостом») правильна техніка — повернути кермо в напрямку заносу, тобто туди, куди рухається задня частина автомобіля, щоб вирівняти траєкторію.", "explSpecific": "Правильно — «Повернуть рулевое колесо в направлении задних колес» (тобто в напрямку заносу). Натискання ножного чи стоянкового гальма під час заносу задніх коліс значно підвищує ризик втрати контролю; поворот керма в протилежний бік лише посилить занос."}, {"num": 868, "text": "Как водителю автомобиля без антиблокировочной тормозной системы ABS противодействовать прямолинейному заносу передних колес?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Нажимать и отпускать ножной тормоз через короткие интервалы.", "Осторожно повернуть рулевое колесо из стороны в сторону.", "Выжать сцепление и отпустить акселератор.", "Потянуть за ручной тормоз и удерживать педаль тормоза нажатой."], "correct": 0, "expl": "На автомобілі БЕЗ антиблокувальної системи водій сам імітує роботу ABS — швидко натискаючи й відпускаючи гальмо короткими інтервалами, щоб колеса не блокувалися повністю.", "explSpecific": "Правильно — «Нажимать и отпускать ножной тормоз через короткие интервалы» (техніка «помпажу», яка замінює відсутню ABS). Обережне погойдування керма чи виключне користування зчепленням не усувають занос передніх коліс так ефективно, як контрольоване переривчасте гальмування; одночасне утримання ручного й ножного гальма надто ризиковане."}, {"num": 869, "text": "Что делать водителю, если двигатель его автомобиля внезапно заглушится во время движения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Убедиться, что ручной тормоз полностью отпущен.", "Включить более низкую передачу.", "Нажать на акселератор, а затем отпустить.", "Подать сигнал и направить автомобиль к обочине дороги."], "correct": 3, "expl": "Якщо двигун раптово заглух під час руху, водій втрачає підсилювач керма й гальм, тому головне — вчасно подати сигнал і безпечно з'їхати на узбіччя, поки автомобіль ще рухається за інерцією.", "explSpecific": "Правильно — «Подать сигнал и направить автомобиль к обочине дороги». Перевірка ручного гальма, перемикання передачі чи натискання газу не запустять двигун і не вирішують головну проблему — потрібно безпечно прибрати автомобіль з проїжджої частини."}, {"num": 870, "text": "Если двигатель заглохнет на полосе медленного движения, как это повлияет на гидроусилитель руля?", "topic": "Обгін та зміна смуги руху", "options": ["Вся жидкость из бачка рулевого управления израсходуется.", "Рулевое колесо автоматически заблокируется.", "Рулевое управление станет тяжелым и затрудненным.", "Рулевое управление станет немного легче и проще."], "correct": 2, "expl": "Якщо двигун глухне під час руху, гідропідсилювач керма перестає працювати (він приводиться від двигуна), тому кермування стає значно важчим і потребує більше зусиль.", "explSpecific": "Правильно — «Рулевое управление станет тяжелым и затрудненным». Кермо не блокується автоматично й не стає легшим без працюючого насоса гідропідсилювача."}, {"num": 871, "text": "Во время движения водитель чувствует, что встречный автомобиль может врезаться в его автомобиль. Как ему следует действовать?", "topic": "Паркування та зупинка", "options": ["Осторожно нажать на педаль тормоза и остановить автомобиль.", "Подать звуковой сигнал, чтобы привлечь внимание другого водителя и уклониться.", "Немедленно задействовать стояночный тормоз, чтобы остановить автомобиль.", "Выключать зажигание двигателя, чтобы остановить автомобиль."], "correct": 1, "expl": "Якщо водій відчуває, що зустрічний автомобіль може врізатися в нього, правильна реакція — подати звуковий сигнал, щоб привернути увагу іншого водія, і одночасно спробувати ухилитися.", "explSpecific": "Правильно — «Подать звуковой сигнал, чтобы привлечь внимание другого водителя и уклониться». Просте гальмування без спроби ухилитися, застосування ручника чи вимкнення запалювання не дають шансу уникнути зіткнення, коли є можливість маневру."}, {"num": 872, "text": "Что делать водителю, если он внезапно столкнулся с опасностью на дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Снизить скорость и резко нажать ножной тормоз.", "Включить ручной и ножной тормоз одновременно.", "Выжать сцепление и выключить зажигание.", "Медленно затормозить и выключить зажигание."], "correct": 0, "expl": "При раптовій небезпеці на дорозі найефективніша реакція — одночасно знизити швидкість і різко, але контрольовано натиснути на ножний гальмо.", "explSpecific": "Правильно — «Снизить скорость и резко нажать ножной тормоз». Одночасне використання ручного й ножного гальма чи вимкнення запалювання під час руху підвищують ризик втрати керування; занадто повільна реакція («медленно затормозить») може не встигнути запобігти зіткненню."}, {"num": 873, "text": "Что делать водителю, если автомобиль сломался на автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Переместить автомобиль на обочину.", "Разместить красный предупреждающий треугольник с левой стороны автомобиля.", "Попросить пассажира встать на дороге, чтобы предупредить других участников движения.", "Включить дальний свет фар."], "correct": 0, "expl": "Якщо автомобіль зламався на автомагістралі, першочергова дія — за можливості перемістити його на узбіччя, подалі від смуги руху.", "explSpecific": "Правильно — «Переместить автомобиль на обочину». Розміщення трикутника прямо на автомагістралі чи прохання пасажира стояти на дорозі — небезпечні дії; дальнє світло не є стандартним сигналом попередження про поломку."}, {"num": 874, "text": "Что следует делать водителю проезжая мимо и столкнувшись с препятствием?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Нажать педаль тормоза и включите более высокую передачу.", "Отключить систему ABS.", "Нажать на тормоз.", "Нажать педаль сцепления и включить пониженную передачу."], "correct": 2, "expl": "Проїжджаючи повз перешкоду і зачепивши її, найпростіша й найнадійніша реакція — просто натиснути на гальмо, не ускладнюючи дію зайвими маневрами.", "explSpecific": "Правильно — «Нажать на тормоз». Перемикання на вищу передачу одночасно з гальмуванням нелогічне й погіршує контроль; відключення ABS у критичний момент прямо шкідливе; натискання зчеплення з пониженою передачею — зайве ускладнення, коли просте гальмування достатнє й ефективніше."}, {"num": 875, "text": "Что следует делать водителю проезжая мимо и столкнувшись с препятствием?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Продолжать давить на педаль тормоза.", "Отключить систему ABS", "Нажать педаль тормоза и включите более высокую передачу.", "Нажать педаль сцепления и включить пониженную передачу."], "correct": 0, "expl": "Та сама ситуація дотичного зіткнення з перешкодою — і найпростіша правильна реакція: продовжувати рівномірно тиснути на гальмо, не відпускаючи його раптово.", "explSpecific": "Правильно — «Продолжать давить на педаль тормоза». Відключення ABS у критичний момент прямо шкідливе; перемикання на вищу передачу під час гальмування нелогічне; натискання зчеплення з пониженою передачею — зайве ускладнення, коли рівномірне гальмування достатнє."}, {"num": 876, "text": "Что делать водителю, если автомобиль сломался на автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Надеть светоотражающий жилет.", "Включить дальний свет фар.", "Разместить красный предупреждающий треугольник с левой стороны автомобиля.", "Попросить пассажира встать на дороге, чтобы предупредить других участников движения."], "correct": 0, "expl": "Якщо автомобіль зламався на автомагістралі, водій повинен надягти світловідбивний жилет, щоб бути максимально помітним для транспорту, що наближається.", "explSpecific": "Правильно — «Надеть светоотражающий жилет». Дальнє світло фар не робить водія самого помітнішим поза автомобілем; розміщення трикутника прямо на автомагістралі чи прохання пасажира стояти на дорозі — небезпечні дії."}, {"num": 877, "text": "Что следует делать водителю при необходимости остановиться в чрезвычайной ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Продолжать давить на тормоза.", "Задействовать и сцепление, и ручной тормоз.", "Слегка надавить на педаль тормоза.", "Нажать педаль тормоза и включить более высокую передачу."], "correct": 0, "expl": "В екстреній ситуації головне правило — продовжувати сильно й безперервно тиснути на педаль гальма до повної зупинки.", "explSpecific": "Правильно — «Продолжать давить на тормоза». Одночасне залучення зчеплення й ручного гальма чи легке натискання применшують ефективність екстреного гальмування; перемикання на вищу передачу під час екстреної зупинки нелогічне й небезпечне."}, {"num": 878, "text": "Что следует делать водителю при необходимости остановиться в чрезвычайной ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Слегка надавить на педаль тормоза.", "Задействовать и сцепление, и ручной тормоз.", "Продолжать давить на педаль тормоза.", "Нажать педаль тормоза и включить более высокую передачу."], "correct": 2, "expl": "Та сама екстрена ситуація — і те саме базове правило екстреного гальмування: сильно й безперервно тиснути на педаль гальма.", "explSpecific": "Правильно — «Продолжать давить на педаль тормоза». Легке натискання не використовує повний гальмівний потенціал; одночасне зчеплення й ручний гальмо чи перемикання на вищу передачу знижують ефективність зупинки саме тоді, коли швидкість найважливіша."}, {"num": 879, "text": "Что должен делать водитель, чтобы избежать аварийной остановки?", "topic": "Паркування та зупинка", "options": ["Левая рука должна быть свободной для применения ручного тормоза, если потребуется.", "Двигаться держа левую ногу на педали тормоза.", "Держать левую ногу на педали сцепления во время движения.", "Соблюдать безопасное расстояние от впереди идущего автомобиля."], "correct": 3, "expl": "Щоб уникнути аварійної (екстреної) зупинки, найкращий спосіб — завчасно тримати безпечну дистанцію від автомобіля попереду, щоб мати достатньо часу й простору для плавної реакції.", "explSpecific": "Правильно — «Соблюдать безопасное расстояние от впереди идущего автомобиля». Тримання лівої руки вільною для ручника чи ноги на педалі зчеплення/гальма без потреби — другорядні звички, які не замінюють головного правила безпечної дистанції."}, {"num": 880, "text": "Что должен делать водитель, чтобы избежать аварийной остановки?", "topic": "Паркування та зупинка", "options": ["Внимательно следить за дорогой.", "Двигаться держа левую ногу на педали тормоза.", "Двигаться держа левую ногу на педали сцепления.", "Левая рука должна быть свободной для применения ручного тормоза, если потребуется."], "correct": 0, "expl": "Головний спосіб уникнути аварійної зупинки — уважно стежити за дорогою і завчасно помічати потенційні небезпеки, а не покладатися на рефлекторні дії в останню мить.", "explSpecific": "Правильно — «Внимательно следить за дорогой». Тримання лівої ноги на педалі гальма чи зчеплення — шкідливі звички, що не замінюють уважності; готовність до ручника «про всяк випадок» так само другорядна порівняно з профілактичним спостереженням."}]);
